function uid(){try{if(window.crypto&&typeof window.crypto.randomUUID==='function')return window.crypto.randomUUID()}catch(e){}return 'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}
function notify(msg){const n=document.getElementById('saveNotice');if(!n)return;n.textContent=msg;n.classList.remove('hidden');clearTimeout(window.__notice);window.__notice=setTimeout(()=>n.classList.add('hidden'),3200)}
