function getTextCase(){return textCaseMode||'title'}
function setTextCase(mode){textCaseMode=mode==='upper'?'upper':'title';save();notify(mode==='upper'?'Padrão de texto: TUDO EM MAIÚSCULAS.':'Padrão de texto: Iniciais em maiúsculas.');render()}
function titleCasePt(value){const particles=new Set(['a','as','o','os','e','de','da','das','do','dos','em','na','nas','no','nos','para','por']);return String(value??'').toLocaleLowerCase('pt-BR').trim().split(/(\s+)/).map((part,i)=>{if(/^\s+$/.test(part)||!part)return part;const lower=part.toLocaleLowerCase('pt-BR');if(i>0&&particles.has(lower))return lower;return lower.charAt(0).toLocaleUpperCase('pt-BR')+lower.slice(1)}).join('')}
function sentenceCasePt(value){return String(value??'').toLocaleLowerCase('pt-BR').replace(/(^|[.!?]\s+)([a-zà-ÿ])/g,(m,p,c)=>p+c.toLocaleUpperCase('pt-BR'))}
function normalizeText(value,kind='field'){const v=String(value??'').trim();if(!v)return '';if(getTextCase()==='upper')return v.toLocaleUpperCase('pt-BR');if(kind==='multiline')return sentenceCasePt(v);return titleCasePt(v)}
function formatPhone(value){const d=String(value??'').replace(/\D/g,'').slice(0,11);if(!d)return '';if(d.length<=2)return `(${d}`;if(d.length<=6)return `(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length===10)return `(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6,10)}`;return `(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7,11)}`}
function bindFieldFormatting(root=document){root.querySelectorAll('input[data-phone], textarea[data-normalize], input[data-normalize]').forEach(el=>{if(el.dataset.formatBound)return;el.dataset.formatBound='1';const applyLive=()=>{if(el.dataset.phone==='true'){el.value=formatPhone(el.value);return}if(el.dataset.normalize==='true'){const start=el.selectionStart,end=el.selectionEnd;if(el.tagName==='TEXTAREA'){const v=el.value;el.value=v?v.charAt(0).toLocaleUpperCase('pt-BR')+v.slice(1):v}else el.value=titleCasePtLive(el.value);try{el.setSelectionRange(start,end)}catch(_){}}};el.addEventListener('input',applyLive);el.addEventListener('blur',()=>{if(el.dataset.phone==='true'){el.value=formatPhone(el.value);return}if(el.dataset.normalize==='true')el.value=normalizeText(el.value,el.tagName==='TEXTAREA'?'multiline':'field')});applyLive()})}
function normalizeFieldValue(key,value){if(key==='emailsGoogle')return String(value||'').trim().toLowerCase();if(key==='telefone'||/telefone|phone|celular/i.test(key))return formatPhone(value);const multiline=new Set(['corpo','motivo','observacoes','anexos','itens','justificativa','quantidades','finalidade']);return normalizeText(value,multiline.has(key)?'multiline':'field')}
function parseGoogleEmails(value){const entries=String(value||'').split(/[;,\n]+/).map(x=>x.trim().toLowerCase()).filter(Boolean);return {emails:[...new Set(entries.filter(x=>/^[a-z0-9._%+-]+@gmail\.com$/.test(x)))],invalid:entries.filter(x=>!/^[a-z0-9._%+-]+@gmail\.com$/.test(x))}}

