const state={docs:[],books:[],loans:[],readers:[],generatedDocs:[],waitlist:[],oficios:[],encaminhamentosMeimei:[],view:'dashboard'};
const titles={dashboard:['Dashboard','Visão geral da instituição'],documentos:['Documentos','Arquivo administrativo'],oficios:['Ofícios','Redação, numeração e histórico de ofícios institucionais'],meimei:['Encaminhamentos Meimei','Geração e arquivo das declarações de encaminhamento de vaga'],gerar:['Gerar Documentos','Encaminhamentos e formulários padronizados'],biblioteca:['Biblioteca','Acervo, usuários e empréstimos'],atas:['Atas','Reuniões e deliberações'],app:['APP','Associação de Pais e Professores'],conselho:['Conselho Escolar','Composição, reuniões e deliberações'],espera:['Lista de Espera','Controle administrativo de solicitações'],agenda:['Agenda','Compromissos e rotinas'],pendencias:['Pendências','Tarefas e prazos'],relatorios:['Relatórios','Informações administrativas'],seguranca:['Segurança','Base de dados, backup e auditoria']};
function dataPayload(){return {app:'CEI Admin',schemaVersion:4,savedAt:new Date().toISOString(),settings:{textCase:getTextCase()},docs:state.docs||[],books:state.books||[],loans:state.loans||[],readers:state.readers||[],generatedDocs:state.generatedDocs||[],waitlist:state.waitlist||[],oficios:state.oficios||[],encaminhamentosMeimei:state.encaminhamentosMeimei||[]}}
function legacyReaderKey(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/\s+/g,' ').trim()}
function reconcileLegacyLoans(){let changed=false;for(const loan of state.loans){if(loan.readerId||!String(loan.person||'').trim())continue;const matches=state.readers.filter(reader=>legacyReaderKey(reader.name)===legacyReaderKey(loan.person));if(matches.length>1)continue;let reader=matches[0];if(!reader){reader={id:uid(),name:String(loan.person).trim(),category:'Não informado',identifier:'',turma:'',active:true,createdAt:new Date().toISOString(),fromHistory:true};state.readers.push(reader);changed=true}loan.readerId=reader.id;changed=true}return changed}
function applyPayload(d){if(!d||d.app!=='CEI Admin')throw new Error('Arquivo de dados não reconhecido.');state.docs=Array.isArray(d.docs)?d.docs:[];state.books=Array.isArray(d.books)?d.books:[];state.loans=Array.isArray(d.loans)?d.loans:[];state.readers=Array.isArray(d.readers)?d.readers:[];state.generatedDocs=Array.isArray(d.generatedDocs)?d.generatedDocs:[];state.waitlist=Array.isArray(d.waitlist)?d.waitlist:[];state.oficios=Array.isArray(d.oficios)?d.oficios:[];state.encaminhamentosMeimei=Array.isArray(d.encaminhamentosMeimei)?d.encaminhamentosMeimei:[];textCaseMode=d.settings?.textCase==='upper'?'upper':'title';return reconcileLegacyLoans()}
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(STORE))db.createObjectStore(STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
const sessionDrafts=new Map();
async function idbGet(key=RECORD_KEY){return sessionDrafts.get(key)}
async function idbPut(value,key=RECORD_KEY){sessionDrafts.set(key,structuredClone(value))}
async function loadLocalData(){try{const d=null;if(d){const migrated=applyPayload(d);syncGeneratedOficios();dataLastSaved=d.savedAt?new Date(d.savedAt):null;if(migrated)await idbPut(dataPayload())}
dataConnected=true;render();updateDataStatus();await initializeShared(!d)}catch(e){console.error(e);dataConnected=false;render();updateDataStatus();notify('Não foi possível acessar o armazenamento do navegador.')}}
function sharedNotice(message){updateSharedStatus(message);let el=document.getElementById('sharedNotice');if(!el){el=document.createElement('div');el.id='sharedNotice';el.style.cssText='padding:10px 16px;background:#fff4cf;color:#473600;font-size:14px;border-bottom:1px solid #e6c75f';document.querySelector('main').prepend(el)}el.textContent=message;el.hidden=sharedActive}
async function writeDataFile(show=true){try{const d=dataPayload();localStorage.setItem('cei-shared-dirty','1');await idbPut(d);dataConnected=true;dataLastSaved=new Date(d.savedAt);queueSharedSave(d);if(show)notify(sharedActive?'Salvo neste computador; enviando ao servidor.':'Alterações pendentes de envio. Verifique a conexão em Segurança.');updateDataStatus();return true}catch(e){dataConnected=false;updateDataStatus();if(show)alert('Não foi possível salvar: '+e.message);return false}}
function save(){writeDataFile(false);return true}
async function sharedRequest(method,payload){const response=await fetch('/api/data/state',{method,cache:'no-store',credentials:'same-origin',headers:{'Content-Type':'application/json'},...(payload?{body:JSON.stringify(payload)}:{})});const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error||`Erro ${response.status}`),{status:response.status});return result}
function sharedSummary(d){return `${(d.books||[]).length} livro(s), ${(d.loans||[]).length} empréstimo(s), ${(d.generatedDocs||[]).length} documento(s) gerado(s) e ${(d.waitlist||[]).length} registro(s) da lista de espera`}
function updateSharedStatus(message){sharedStatus=message;const el=document.getElementById('sharedStatus');if(el)el.textContent=message}
async function payloadHash(d){const normalized={...d};delete normalized.savedAt;const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(normalized)));return Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('')}
async function rememberShared(data,revision){localStorage.setItem('cei-shared-mode','1');localStorage.setItem('cei-shared-revision',revision);if(await payloadHash(data)===await payloadHash(dataPayload()))localStorage.removeItem('cei-shared-dirty')}
const sharedCollections=['docs','books','loans','readers','generatedDocs','waitlist','oficios','encaminhamentosMeimei'];
function mergeShared(base,local,remote){
 const out=JSON.parse(JSON.stringify(remote)),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 for(const key of [...sharedCollections,'settings']){
  if(key==='settings'){if(!same(base[key],local[key])){if(!same(remote[key],base[key])&&!same(remote[key],local[key]))throw Error('O padrão de preenchimento foi alterado por outra pessoa.');out[key]=local[key]}continue}
  const old=new Map((base[key]||[]).map(x=>[x.id,x])),next=new Map((local[key]||[]).map(x=>[x.id,x])),current=new Map((remote[key]||[]).map(x=>[x.id,x]));
  for(const id of new Set([...old.keys(),...next.keys()])){const a=old.get(id),b=next.get(id),c=current.get(id);if(same(a,b))continue;if(!same(a,c)&&!same(b,c))throw Error('O mesmo registro foi alterado em outro computador. Seu rascunho foi preservado em Segurança.');if(b)current.set(id,b);else current.delete(id)}
  out[key]=[...current.values()];
 }
 out.savedAt=new Date().toISOString();return out;
}
function queueSharedSave(data=dataPayload()){
 data=JSON.parse(JSON.stringify(data));const localBase=JSON.parse(JSON.stringify(scheduledPayload||sharedBase));scheduledPayload=data;
 sharedQueue=sharedQueue.then(async()=>{
  if(!sharedBase||!sharedActive)throw Error('A conexão precisa ser retomada em Segurança.');
  const base=localBase||sharedBase;let sent=mergeShared(base,data,sharedBase);
  sharedNotice('Salvando no servidor…');document.getElementById('sharedNotice').hidden=false;
  let result;
  for(let attempt=0;attempt<4;attempt++){
   try{result=await sharedRequest('PUT',{revision:sharedRevision,data:sent});break}catch(error){if(error.status===423){await new Promise(r=>setTimeout(r,400*(attempt+1)));continue}if(error.status!==409)throw error;const remote=await sharedRequest('GET');sent=mergeShared(base,data,remote.data);sharedRevision=remote.revision;}
  }
  if(!result)throw Error('Servidor ocupado. Tente salvar novamente.');
  const unchanged=await payloadHash(dataPayload())===await payloadHash(data);
  if(result.data)sent=result.data;sharedRevision=result.revision;sharedBase=JSON.parse(JSON.stringify(sent));await idbPut(sharedBase,'shared-base');sharedActive=true;
  if(unchanged){applyPayload(sent);await idbPut(sent);localStorage.removeItem('cei-shared-dirty')}else{const latest=mergeShared(data,dataPayload(),sent);applyPayload(latest);await idbPut(latest)}
  await rememberShared(sent,result.revision);sharedNotice('Salvo no servidor às '+new Date().toLocaleTimeString('pt-BR')+'.');document.getElementById('sharedNotice').hidden=false;updateDataStatus();
 }).catch(async error=>{sharedActive=false;await idbPut(dataPayload(),'recovery');sharedNotice('Não salvo no servidor: '+error.message+' Abra Segurança para tentar novamente.');});return sharedQueue;
}
window.inspectSharedData=async()=>{try{const remote=await sharedRequest('GET');updateSharedStatus('Servidor: '+sharedSummary(remote.data)+'. Alterações compartilhadas automaticamente.')}catch(error){updateSharedStatus(error.message)}};
async function adoptShared(remote){applyPayload(remote.data);sharedBase=JSON.parse(JSON.stringify(remote.data));scheduledPayload=JSON.parse(JSON.stringify(remote.data));await idbPut(sharedBase,'shared-base');await idbPut(remote.data);sharedRevision=remote.revision;sharedActive=true;dataLastSaved=new Date(remote.data.savedAt);await rememberShared(dataPayload(),remote.revision);localStorage.removeItem('cei-shared-dirty');updateSharedStatus('Conectado ao servidor. Alterações compartilhadas automaticamente.');const notice=document.getElementById('sharedNotice');if(notice)notice.hidden=true}
async function initializeShared(fresh){try{const local=dataPayload(),remote=await sharedRequest('GET'),base=await idbGet('shared-base'),dirty=localStorage.getItem('cei-shared-dirty')==='1';
 if(dirty&&base){sharedBase=base;sharedRevision=localStorage.getItem('cei-shared-revision');sharedActive=true;await queueSharedSave(local)}else{if(!fresh&&await payloadHash(local)!==await payloadHash(remote.data)&&(!base||dirty))await idbPut(local,'recovery');await adoptShared(remote)}
 render();updateDataStatus();
 }catch(error){sharedActive=false;sharedNotice('Não foi possível conectar ao servidor. As alterações ainda não foram compartilhadas. '+error.message)}}
window.retryShared=async()=>{if(localStorage.getItem('cei-shared-dirty')==='1'){await sharedQueue;if(!sharedBase)sharedBase=await idbGet('shared-base');scheduledPayload=sharedBase;sharedActive=!!sharedBase;await queueSharedSave()}else await initializeShared(false);};
window.exportLocalDraft=async()=>{const draft=await idbGet('recovery');if(!draft)return alert('Não há rascunho preservado neste navegador.');downloadJson(draft,'cei-rascunho-preservado.json')};
window.useServerVersion=async()=>{if(!confirm('Carregar a versão do servidor? As alterações pendentes deste computador serão preservadas como rascunho para download.'))return;try{await sharedQueue;await idbPut(dataPayload(),'recovery');await adoptShared(await sharedRequest('GET'));render()}catch(error){alert(error.message)}};
async function importMissing(draft){if(localStorage.getItem('cei-shared-dirty')==='1')throw Error('Resolva primeiro as alterações pendentes: tente salvar novamente ou use a versão do servidor, preservando o rascunho.');if(draft?.app!=='CEI Admin')throw Error('Arquivo de dados não reconhecido.');await sharedQueue;const remote=await sharedRequest('GET'),merged=JSON.parse(JSON.stringify(remote.data));let added=0,conflicts=0;for(const key of sharedCollections){const ids=new Map(merged[key].map(x=>[x.id,x]));for(const item of draft[key]||[]){if(!item.id)continue;if(!ids.has(item.id)){merged[key].push(item);ids.set(item.id,item);added++}else if(JSON.stringify(ids.get(item.id))!==JSON.stringify(item))conflicts++}}if(!confirm(`Acrescentar ${added} registros ausentes ao servidor? ${conflicts} registros diferentes com o mesmo código serão mantidos como estão no servidor. O rascunho original continuará preservado.`))return;await adoptShared(remote);applyPayload(merged);await writeDataFile(false);await sharedQueue;render();}
window.recoverLocalDraft=async()=>{try{const draft=await idbGet('recovery');if(!draft)return alert('Nenhum registro antigo preservado neste navegador.');await importMissing(draft)}catch(error){alert(error.message)}};
window.downloadDataCopy=async()=>{try{const blob=new Blob([JSON.stringify(dataPayload(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cei-admin-dados.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Cópia da base exportada.')}catch(e){alert('Não foi possível exportar: '+e.message)}};
window.handleDataFallback=async input=>{try{const file=input.files?.[0];if(file){const draft=JSON.parse(await file.text());await idbPut(draft,'recovery');await importMissing(draft)}}catch(error){alert(error.message)}finally{input.value=''}};
window.importDataFile=()=>document.getElementById('dataFileFallback').click();
