if(state.view==='dashboard')return a.innerHTML=`<div class="base-summary">💾 Base carregada: <b>${state.waitlist.length}</b> vaga(s) na lista de espera • <b>${state.oficios.length}</b> ofício(s) • <b>${state.docs.length}</b> documento(s)</div><div class="grid"><div class="card stat">Documentos<b>${state.docs.length}</b><span class="muted">cadastrados</span></div><div class="card stat">Livros<b>${state.books.length}</b><span class="muted">no acervo</span></div><div class="card stat">Emprestados<b>${state.loans.filter(l=>!l.returned).length}</b><span class="muted">fora do acervo</span></div><div class="card stat">Protegidos<b>${state.docs.filter(d=>d.protected).length}</b><span class="muted">documentos críticos</span></div></div><div class="panel"><h2>Últimos documentos</h2>${docTable(state.docs.slice().reverse().slice(0,8))}</div>`;
