function generatedArchiveItems(){
  const out=[];
  (state.oficios||[]).forEach(o=>out.push({kind:'oficio',id:o.id,name:`Ofício ${o.numero||''}/${o.ano||''}`,date:formatDate(o.data),reference:o.destinatario||o.assunto||'—',sort:o.updatedAt||o.createdAt||o.data||'',signed:!!o.signedPdfData}));
  (state.generatedDocs||[]).filter(g=>g.template!=='oficio').forEach(g=>out.push({kind:g.template||'outros',id:g.id,name:g.name||'Documento',date:g.date||'',reference:g.reference||'—',sort:g.createdAt||g.date||''}));
  return out.sort((x,y)=>String(y.sort).localeCompare(String(x.sort)));
}
