function syncGeneratedOficios(){let changed=false;for(const g of (state.generatedDocs||[]).filter(x=>x.template==='oficio')){if((state.oficios||[]).some(o=>o.id===g.id))continue;let numero=String(g.data?.numero||'').trim(),ano=String(new Date().getFullYear());const m=numero.match(/^(.+?)\s*\/\s*(\d{4})$/);if(m){numero=m[1];ano=m[2]}state.oficios.push({id:g.id,numero:numero||oficioNextNumber(),ano,data:g.data?.data||today(),destinatario:g.data?.destinatario||'',assunto:g.data?.assunto||'',corpo:g.data?.corpo||'',corpoHtml:'',anexos:g.data?.anexos||'',assinatura:'Alysson Christiano Primor',funcao:'Diretor Adjunto — CEI Lindolpho José da Silva',status:'finalizado',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});changed=true}if(changed)writeDataFile(false)}
function docTable(docs){if(!docs.length)return '<p class="muted">Nenhum documento cadastrado.</p>';return `<table class="table"><thead><tr><th>Documento</th><th>Categoria</th><th>Status</th><th>Proteção</th><th>Ação</th></tr></thead><tbody>${docs.map(d=>`<tr><td><b>${esc(d.name)}</b><br><span class="muted">${esc(d.date)}</span></td><td>${esc(d.cat)}</td><td><span class="badge">${esc(d.status)}</span></td><td>${d.protected?'🛡 Protegido':'—'}</td><td><button onclick="archiveDoc('${d.id}')">${d.status==='Ativo'?'Arquivar':'Restaurar'}</button></td></tr>`).join('')}</tbody></table>`}
let libraryCase='title';
function libraryDisplayText(v){v=String(v||'');return libraryCase==='upper'?v.toLocaleUpperCase('pt-BR'):libraryCase==='lower'?v.toLocaleLowerCase('pt-BR'):titleCasePt(v)}
function libraryToday(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`}
function loanDateIso(value){const v=String(value||'');if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);return m?`${m[3]}-${m[2]}-${m[1]}`:''}
function loanDateLabel(value){const iso=loanDateIso(value);return iso?formatDate(iso):'—'}
function activeBookLoans(bookId){return (state.loans||[]).filter(l=>l.bookId===bookId&&!l.returned)}
function bookCopies(b){return Math.max(1,Number.parseInt(b.quantity,10)||1)}
function bookAvailable(b){return Math.max(0,bookCopies(b)-activeBookLoans(b.id).length)}
function loanOverdue(l){const due=loanDateIso(l.due);return !l.returned&&!!due&&due<libraryToday()}
function loanTitle(l){return l.bookTitle||state.books.find(b=>b.id===l.bookId)?.title||'Livro removido'}
window.setLibraryView=view=>{window.__libraryView=view;window.__librarySearch='';window.__libraryLoanFilter='all';renderLibrary(document.getElementById('app'))};
window.setLibrarySearch=(input,kind)=>{const start=input.selectionStart,end=input.selectionEnd;window[kind]=input.value;renderLibrary(document.getElementById('app'));const next=document.getElementById(kind==='__bookSearch'?'bookSearch':kind==='__libraryReaderSearch'?'readerSearch':'circulationSearch');if(next){next.focus();next.setSelectionRange(start,end)}};
function renderLibrary(a){
  const q=(window.__bookSearch||'').trim().toLocaleLowerCase('pt-BR'), initial=window.__bookInitial||'';
  let books=state.books.filter(b=>{const authors=(b.authors||[]).join(' ');const hay=[b.title,b.author,authors,b.publisher,b.cutter,b.notes].join(' ').toLocaleLowerCase('pt-BR');return (!q||hay.includes(q))&&(!initial||libraryDisplayText(b.title).charAt(0).toLocaleUpperCase('pt-BR')===initial)});
  const initials='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const view=window.__libraryView||'catalog',active=(state.loans||[]).filter(l=>!l.returned),overdue=active.filter(loanOverdue).length,available=state.books.reduce((n,b)=>n+bookAvailable(b),0);
  a.innerHTML=`<section class="library-hero"><div><span class="eyebrow">BIBLIOTECA DO CEI</span><h2>Acervo e circulação</h2><p>Cadastro, empréstimos, devoluções e histórico.</p></div><div class="library-hero-actions"><button onclick="openLoanModal()">+ Registrar empréstimo</button><button onclick="openReaderModal()">+ Cadastrar usuário</button><button class="primary" onclick="openBookModal()">+ Novo livro</button></div></section>
  <div class="library-stats"><div><span>Títulos</span><b>${state.books.length}</b></div><div><span>Exemplares disponíveis</span><b>${available}</b></div><div><span>Empréstimos em aberto</span><b>${active.length}</b></div><div><span>Em atraso</span><b>${overdue}</b></div></div>
  <div class="library-view-tabs" role="tablist" aria-label="Seções da biblioteca"><button role="tab" aria-selected="${view==='catalog'}" class="${view==='catalog'?'active':''}" onclick="setLibraryView('catalog')">Acervo</button><button role="tab" aria-selected="${view==='active'}" class="${view==='active'?'active':''}" onclick="setLibraryView('active')">Empréstimos em aberto${active.length?` (${active.length})`:''}</button><button role="tab" aria-selected="${view==='history'}" class="${view==='history'?'active':''}" onclick="setLibraryView('history')">Histórico</button><button role="tab" aria-selected="${view==='readers'}" class="${view==='readers'?'active':''}" onclick="setLibraryView('readers')">Usuários (${state.readers.length})</button></div>
  ${view==='readers'?renderReaders():view!=='catalog'?renderCirculation(view):`<div class="panel library-panel"><div class="library-toolbar simple"><div class="search-wrap"><span>⌕</span><input id="bookSearch" value="${esc(window.__bookSearch||'')}" placeholder="Pesquisar por título, autor ou código Cutter..." oninput="setLibrarySearch(this,'__bookSearch')"></div></div>
  <div class="initial-filter"><button class="${!initial?'active':''}" onclick="window.__bookInitial='';renderLibrary(document.getElementById('app'))">Todos</button>${initials.map(x=>`<button class="${initial===x?'active':''}" onclick="window.__bookInitial='${x}';renderLibrary(document.getElementById('app'))">${x}</button>`).join('')}</div>
  <div class="case-toolbar"><span>Exibição dos títulos:</span><button class="${libraryCase==='title'?'active':''}" onclick="libraryCase='title';renderLibrary(document.getElementById('app'))">Iniciais maiúsculas</button><button class="${libraryCase==='upper'?'active':''}" onclick="libraryCase='upper';renderLibrary(document.getElementById('app'))">MAIÚSCULAS</button><button class="${libraryCase==='lower'?'active':''}" onclick="libraryCase='lower';renderLibrary(document.getElementById('app'))">minúsculas</button></div>
  <div class="book-result-head"><span>${books.length} resultado(s)</span><span class="muted">Disponibilidade calculada pelos empréstimos em aberto</span></div>${bookTable(books)}</div>`}`;
}
function renderCirculation(view){
  const q=(window.__librarySearch||'').trim().toLocaleLowerCase('pt-BR'),filter=window.__libraryLoanFilter||'all';
  const rows=(state.loans||[]).filter(l=>view==='history'||!l.returned).filter(l=>filter==='late'?loanOverdue(l):filter==='returned'?!!l.returned:filter==='open'?!l.returned:true).filter(l=>!q||[loanTitle(l),l.bookCutter,l.person,l.turma,l.copyNumber].join(' ').toLocaleLowerCase('pt-BR').includes(q)).slice().sort((a,b)=>view==='active'?(Number(loanOverdue(b))-Number(loanOverdue(a))||String(loanDateIso(a.due)).localeCompare(String(loanDateIso(b.due)))):String(b.createdAt||loanDateIso(b.date)||'').localeCompare(String(a.createdAt||loanDateIso(a.date)||'')));
  return `<div class="panel library-panel"><div class="circulation-toolbar"><input id="circulationSearch" aria-label="Pesquisar empréstimos" value="${esc(window.__librarySearch||'')}" placeholder="Pesquisar livro, Cutter, responsável ou turma..." oninput="setLibrarySearch(this,'__librarySearch')"><select aria-label="Filtrar empréstimos" onchange="window.__libraryLoanFilter=this.value;renderLibrary(document.getElementById('app'))"><option value="all" ${filter==='all'?'selected':''}>Todos</option><option value="late" ${filter==='late'?'selected':''}>Em atraso</option>${view==='history'?`<option value="open" ${filter==='open'?'selected':''}>Em aberto</option><option value="returned" ${filter==='returned'?'selected':''}>Devolvidos</option>`:''}</select></div><div class="book-result-head"><span>${rows.length} registro(s)</span><span class="muted">${view==='active'?'Empréstimos aguardando devolução':'Empréstimos e devoluções registrados'}</span></div>${rows.length?`<div class="book-table-wrap"><table class="table circulation-table"><thead><tr><th>Livro / exemplar</th><th>Responsável</th><th>Retirada</th><th>Devolução prevista</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(l=>`<tr><td><b>${esc(loanTitle(l))}</b><small>${esc(l.bookCutter||state.books.find(b=>b.id===l.bookId)?.cutter||'—')}${l.copyNumber?` · Exemplar ${Number(l.copyNumber)}`:''}</small></td><td>${l.readerId&&state.readers.some(r=>r.id===l.readerId)?`<button class="reader-link" onclick="openReaderProfile('${l.readerId}')">${esc(state.readers.find(r=>r.id===l.readerId).name)}</button>`:esc(l.person||'—')}${l.turma?`<small>${esc(l.turma)}</small>`:''}</td><td>${esc(loanDateLabel(l.date))}</td><td>${esc(loanDateLabel(l.due))}${l.renewals?.length?`<small>${l.renewals.length} renovação(ões)</small>`:''}</td><td><span class="loan-status ${l.returned?'returned':loanOverdue(l)?'late':'open'}">${l.returned?`Devolvido em ${esc(loanDateLabel(l.returnDate))}`:loanOverdue(l)?'Em atraso':'Em dia'}</span>${l.returnCondition&&l.returnCondition!=='Bom estado'?`<small>${esc(l.returnCondition)}</small>`:''}</td><td class="book-actions">${l.returned?'—':`<button onclick="openReturnModal('${l.id}')">Devolver</button><button onclick="openRenewModal('${l.id}')">Renovar</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="library-empty"><b>Nenhum registro encontrado.</b><span>Altere a pesquisa ou o filtro para consultar outros empréstimos.</span></div>'}</div>`;
}
function readerLoans(id){return (state.loans||[]).filter(l=>l.readerId===id)}
function renderReaders(){
  const q=searchFold(window.__libraryReaderSearch||'');
  const readers=(state.readers||[]).filter(r=>!q||searchFold(`${r.name} ${r.identifier||''} ${r.category||''} ${r.turma||''}`).includes(q)).slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR'));
  const selected=state.readers.find(r=>r.id===window.__libraryReaderId);
  return `<div class="panel library-panel"><div class="circulation-toolbar"><input id="readerSearch" value="${esc(window.__libraryReaderSearch||'')}" placeholder="Pesquisar usuário por nome, código ou turma..." aria-label="Pesquisar usuários" oninput="setLibrarySearch(this,'__libraryReaderSearch')"><button class="primary" onclick="openReaderModal()">+ Novo usuário</button></div><p class="hint">Cadastre a pessoa responsável pelo livro. Empréstimos antigos foram associados pelo nome quando havia apenas uma correspondência.</p>${readers.length?`<div class="book-table-wrap"><table class="table reader-table"><thead><tr><th>Nome</th><th>Tipo / código</th><th>Em aberto</th><th>Total</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${readers.map(r=>{const loans=readerLoans(r.id);return `<tr><td><b>${esc(r.name)}</b>${r.turma?`<small>${esc(r.turma)}</small>`:''}</td><td>${esc(r.category||'—')}${r.identifier?`<small>${esc(r.identifier)}</small>`:''}</td><td>${loans.filter(l=>!l.returned).length}</td><td>${loans.length}</td><td><span class="loan-status ${r.active===false?'returned':'open'}">${r.active===false?'Inativo':'Ativo'}</span></td><td class="book-actions"><button onclick="openReaderProfile('${r.id}')">Histórico</button><button onclick="openReaderModal('${r.id}')">Editar</button><button onclick="toggleReaderActive('${r.id}')">${r.active===false?'Reativar':'Desativar'}</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="library-empty"><b>Nenhum usuário encontrado.</b><span>Cadastre um responsável para acompanhar seus empréstimos.</span></div>'}${selected?renderReaderProfile(selected):''}</div>`;
}
function renderReaderProfile(reader){
  const loans=readerLoans(reader.id).slice().sort((a,b)=>String(b.createdAt||loanDateIso(b.date)||'').localeCompare(String(a.createdAt||loanDateIso(a.date)||'')));
  return `<section class="reader-profile"><div class="reader-profile-head"><div><h3>Histórico de ${esc(reader.name)}</h3><p>${esc(reader.category||'Usuário')}${reader.identifier?` · Código ${esc(reader.identifier)}`:''} · ${loans.length} empréstimo(s)</p></div><button onclick="window.__libraryReaderId='';renderLibrary(document.getElementById('app'))" aria-label="Fechar histórico">Fechar</button></div>${loans.length?`<div class="book-table-wrap"><table class="table circulation-table"><thead><tr><th>Livro</th><th>Retirada</th><th>Prazo</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${loans.map(l=>`<tr><td><b>${esc(loanTitle(l))}</b><small>${esc(l.bookCutter||'—')}${l.copyNumber?` · Exemplar ${Number(l.copyNumber)}`:''}</small></td><td>${esc(loanDateLabel(l.date))}</td><td>${esc(loanDateLabel(l.due))}</td><td><span class="loan-status ${l.returned?'returned':loanOverdue(l)?'late':'open'}">${l.returned?`Devolvido em ${esc(loanDateLabel(l.returnDate))}`:loanOverdue(l)?'Em atraso':'Em aberto'}</span></td><td class="book-actions">${l.returned?'—':`<button onclick="openReturnModal('${l.id}')">Devolver</button><button onclick="openRenewModal('${l.id}')">Renovar</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum empréstimo registrado para esta pessoa.</p>'}</section>`;
}
window.openReaderProfile=id=>{window.__libraryView='readers';window.__libraryReaderId=id;renderLibrary(document.getElementById('app'));document.querySelector('.reader-profile')?.scrollIntoView({block:'nearest',behavior:'smooth'})};
function bookAuthors(b){return (b.authors&&b.authors.length?b.authors:String(b.author||'').split(/\s*;\s*/).filter(Boolean))}
function bookTable(books){if(!books.length)return '<div class="library-empty"><b>Nenhum livro encontrado.</b><span>Altere a letra ou a pesquisa, ou cadastre um novo título.</span></div>';return `<div class="book-table-wrap"><table class="table book-table"><thead><tr><th>Cutter</th><th>Título</th><th>Autor(es)</th><th>Editora / ano</th><th>Disponibilidade</th><th>Ações</th></tr></thead><tbody>${books.map(b=>`<tr><td><code>${esc(b.cutter||'—')}</code></td><td><b>${esc(libraryDisplayText(b.title))}</b></td><td>${esc(bookAuthors(b).join('; ')||'—')}</td><td>${esc([b.publisher,b.year].filter(Boolean).join(' • ')||'—')}</td><td><span class="loan-status ${bookAvailable(b)?'open':'late'}">${bookAvailable(b)} de ${bookCopies(b)} disponível(is)</span></td><td class="book-actions"><button onclick="openLoanModal('${b.id}')" ${bookAvailable(b)?'':'disabled title="Todos os exemplares estão emprestados"'}>Emprestar</button><button onclick="showBook('${b.id}')">Consultar</button><button onclick="editBook('${b.id}')">Editar</button><button class="danger-lite" onclick="deleteBook('${b.id}')">Excluir</button></td></tr>`).join('')}</tbody></table></div>`}
window.editBook=id=>{const b=state.books.find(x=>x.id===id);if(!b)return;openBookModal(b)};
window.deleteBook=id=>{const b=state.books.find(x=>x.id===id);if(!b)return;if((state.loans||[]).some(l=>l.bookId===id))return alert('Este livro possui empréstimos registrados. Preserve o cadastro para manter o histórico.');if(!confirm(`Excluir "${b.title}" do acervo?`))return;state.books=state.books.filter(x=>x.id!==id);save();renderLibrary(document.getElementById('app'));notify('Livro excluído do acervo.')};
window.showBook=id=>{const b=state.books.find(x=>x.id===id);if(!b)return;alert(`${libraryDisplayText(b.title)}\nCutter: ${b.cutter||'—'}\nAutor(es): ${bookAuthors(b).join('; ')||'—'}\nEditora: ${b.publisher||'—'}\nAno: ${b.year||'—'}\nExemplares: ${bookAvailable(b)} disponíveis de ${bookCopies(b)}\nObservações: ${b.notes||'—'}`)};
function authorRow(value=''){const row=document.createElement('div');row.className='author-row';row.innerHTML=`<input class="book-author-item" data-normalize="true" placeholder="Nome do autor" value="${esc(value)}"><button type="button" title="Remover autor">×</button>`;row.querySelector('button').onclick=()=>{if(document.querySelectorAll('.author-row').length>1)row.remove();else row.querySelector('input').value=''};document.getElementById('bookAuthors').appendChild(row)}
window.addAuthorField=()=>authorRow('');
function getAuthors(){return [...document.querySelectorAll('.book-author-item')].map(e=>normalizeText(e.value)).filter(Boolean)}
function cutterBase(title,authors){const clean=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9 ]/g,' ').trim();const particles=new Set(['da','de','do','das','dos','e']);const parts=clean(authors[0]||title).split(/\s+/).filter(Boolean);let surname=[...parts].reverse().find(x=>!particles.has(x.toLowerCase()))||parts[0]||'L';const letter=surname.charAt(0).toUpperCase()||'L';let h=0;for(const ch of surname.toLowerCase())h=(h*31+ch.charCodeAt(0))%900;const number=String(100+h).slice(-3);const words=clean(title).split(/\s+/).filter(x=>x&&!['o','a','os','as','um','uma','de','da','do','das','dos','e'].includes(x.toLowerCase()));const suffix=(words[0]||title||'l').charAt(0).toLowerCase();return letter+number+suffix}
function cutterConflict(code,ignoreId=''){return state.books.find(b=>b.id!==ignoreId&&String(b.cutter||'').toUpperCase()===String(code||'').toUpperCase())}
window.suggestCutter=()=>{const title=document.getElementById('bookTitle').value.trim(),authors=getAuthors();if(!title&&!authors.length)return alert('Informe ao menos o título ou um autor.');const base=cutterBase(title,authors),editId=document.getElementById('bookModal').dataset.editId;let candidate=base,n=2;while(cutterConflict(candidate,editId))candidate=base+n++;document.getElementById('bookCutter').value=candidate;checkCutter();};
function checkCutter(){const e=document.getElementById('bookCutter'),status=document.getElementById('cutterStatus');if(!e||!status)return;const code=e.value.trim(),hit=cutterConflict(code,document.getElementById('bookModal').dataset.editId);status.className='field-help '+(hit?'conflict':'available');status.textContent=!code?'Informe ou gere um código Cutter.':hit?`Código já utilizado por: ${hit.title}`:'Código disponível no acervo.'}
window.openBookModal=(b=null)=>{document.getElementById('bookModal').classList.remove('hidden');document.getElementById('bookModal').dataset.editId=b?.id||'';document.getElementById('bookModalTitle').textContent=b?'Editar livro':'Cadastrar livro';document.getElementById('bookTitle').value=b?.title||'';document.getElementById('bookCutter').value=b?.cutter||'';document.getElementById('bookPublisher').value=b?.publisher||'';document.getElementById('bookYear').value=b?.year||'';document.getElementById('bookNotes').value=b?.notes||'';document.getElementById('bookAuthors').innerHTML='';const authors=b?bookAuthors(b):[];(authors.length?authors:['']).forEach(authorRow);checkCutter()};window.closeBookModal=()=>document.getElementById('bookModal').classList.add('hidden');
function searchFold(value){
  return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
}
function waitStatusLabel(status){
  const labels={recebida:'Recebida',aceitou:'Aceitou a vaga',rejeitou:'Recusou a vaga',sem_resposta:'Não respondeu',telefone_inativo:'Telefone inativo',contato:'Enviada mensagem',matriculou:'Fez a matrícula',retirou_encaminhamento:'Retirou encaminhamento',outro_local:'Solicitou vaga em outro local',outro:'Outro',finalizada:'Finalizada'};
  return labels[status]||String(status??'');
}
function renderWaitlist(a){
  const q=document.getElementById('waitSearch')?.value||'';
  const filter=document.getElementById('waitFilter')?.value||'';
  const birth=document.getElementById('waitBirth')?.value||'';
  const received=document.getElementById('waitReceived')?.value||'';
  const turma=document.getElementById('waitTurma')?.value||'';
  const destino=document.getElementById('waitDestino')?.value||'';
  const fq=searchFold(q);
  const rows=(state.waitlist||[]).filter(w=>(!fq||searchFold([w.crianca,w.responsavel,w.telefone,w.destino,w.turma].join(' ')).includes(fq))&&(!filter||w.status===filter)&&(!birth||w.nascimento===birth)&&(!received||w.recebimento===received)&&(!turma||w.turma===turma)&&(!destino||w.destino===destino));
  const open=(state.waitlist||[]).filter(w=>!['finalizada','matriculou','rejeitou'].includes(w.status)).length;
  a.innerHTML=`<div class="grid"><div class="card stat">Vagas recebidas<b>${state.waitlist.length}</b><span class="muted">registradas</span></div><div class="card stat">Em andamento<b>${open}</b><span class="muted">aguardando conclusão</span></div><div class="card stat">Matrículas<b>${state.waitlist.filter(w=>w.status==='matriculou').length}</b><span class="muted">realizadas</span></div><div class="card stat">Sem resposta<b>${state.waitlist.filter(w=>w.status==='sem_resposta').length}</b><span class="muted">aguardando família</span></div></div><div class="panel"><div class="toolbar wait-toolbar"><input id="waitSearch" value="${esc(q)}" placeholder="Pesquisar criança, responsável ou telefone..." oninput="render()"><select id="waitFilter" onchange="render()"><option value="">Todos os status</option>${['recebida','aceitou','rejeitou','sem_resposta','telefone_inativo','matriculou','retirou_encaminhamento','outro_local'].map(x=>`<option value="${x}" ${filter===x?'selected':''}>${waitStatusLabel(x)}</option>`).join('')}</select><select id="waitTurma" onchange="render()"><option value="">Todas as turmas</option>${['Berçário I','Berçário II','Jardim','Pré I','Pré II'].map(x=>`<option ${turma===x?'selected':''}>${x}</option>`).join('')}</select><select id="waitDestino" onchange="render()"><option value="">Todos os locais</option>${['CEI Lindolpho José da Silva','Meimei'].map(x=>`<option ${destino===x?'selected':''}>${x}</option>`).join('')}</select><label class="compact-filter">Nascimento<input id="waitBirth" type="date" value="${esc(birth)}" onchange="render()"></label><label class="compact-filter">Recebimento<input id="waitReceived" type="date" value="${esc(received)}" onchange="render()"></label><button class="primary" onclick="openWaitModal()">+ Registrar vaga recebida</button></div><p class="hint">A turma e o local são registrados exatamente conforme o encaminhamento recebido da Secretaria. A pesquisa por nome ignora diferenças entre maiúsculas, minúsculas e acentos.</p>${waitTable(rows)}</div>`;
}
function waitTable(rows){if(!rows.length)return'<p class="muted">Nenhuma vaga encontrada com os filtros informados.</p>';return`<table class="table"><thead><tr><th>Criança</th><th>Local</th><th>Turma</th><th>Família</th><th>Recebimento</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(w=>`<tr><td><b>${esc(w.crianca)}</b><br><span class="muted">Nascimento: ${esc(formatDate(w.nascimento))}</span></td><td>${esc(w.destino)}</td><td>${esc(w.turma)}</td><td>${esc(w.responsavel)}<br><span class="muted">${esc(w.telefone||'')}</span></td><td>${esc(formatDate(w.recebimento))}</td><td><span class="badge">${esc(waitStatusLabel(w.status))}</span>${w.status==='rejeitou'&&w.rejectionReason?`<br><span class="muted">${esc(w.rejectionReason)}</span>`:''}</td><td><button onclick="openHistoryModal('${w.id}')">Andamento</button> <button onclick="printWaitReport('${w.id}')">Relatório</button></td></tr>`).join('')}</tbody></table>`}
function formatDate(v){if(!v)return'—';const p=v.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:v}
window.openWaitModal=()=>{document.getElementById('waitForm').innerHTML=`<div class="form-grid"><label>Nome da criança *<input id="wCrianca" data-normalize="true" placeholder="Nome completo"></label><label>Data de nascimento *<input id="wNascimento" type="date"></label><label>Local *<select id="wDestino"><option>CEI Lindolpho José da Silva</option><option>Meimei</option></select></label><label>Turma *<select id="wTurma"><option value="">Selecione...</option><option>Berçário I</option><option>Berçário II</option><option>Jardim</option><option>Pré I</option><option>Pré II</option></select></label><label>Nome do responsável *<input id="wResponsavel" data-normalize="true" placeholder="Nome completo"></label><label>Telefone<input id="wTelefone" data-phone="true" inputmode="numeric" maxlength="15" placeholder="(47) 99999-9999"></label><label>Data de recebimento da Secretaria *<input id="wRecebimento" type="date" value="${today()}"></label><label class="full">Observações iniciais<textarea id="wObs" data-normalize="true"></textarea></label></div>`;document.getElementById('waitModal').classList.remove('hidden');bindFieldFormatting(document.getElementById('waitForm'))}
window.closeWaitModal=()=>document.getElementById('waitModal').classList.add('hidden');
window.saveWaitRecord=()=>{const g=id=>document.getElementById(id).value.trim();const w={id:uid(),crianca:normalizeText(g('wCrianca')),nascimento:g('wNascimento'),destino:g('wDestino'),turma:g('wTurma'),responsavel:normalizeText(g('wResponsavel')),telefone:formatPhone(g('wTelefone')),recebimento:g('wRecebimento'),observacoes:normalizeText(g('wObs'),'multiline'),status:'recebida',history:[]};if(!w.crianca||!w.nascimento||!w.destino||!w.responsavel||!w.recebimento||!w.turma)return alert('Preencha todos os campos obrigatórios.');w.history.push({id:uid(),date:today(),time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),type:'Recebimento da vaga',channel:'Secretaria de Educação',response:'Vaga recebida para providências.',status:'recebida'});state.waitlist.push(w);if(!save()){state.waitlist.pop();return}closeWaitModal();render();notify('Vaga salva com sucesso no CEI Admin.')}
window.openHistoryModal=id=>{const w=state.waitlist.find(x=>x.id===id);if(!w)return;document.getElementById('historyModal').dataset.wait=id;document.getElementById('historyForm').innerHTML=`<div class="panel"><b>${esc(w.crianca)}</b> · ${esc(w.destino)} · ${esc(w.turma)}<br><span class="muted">Responsável: ${esc(w.responsavel)} · ${esc(w.telefone||'telefone não informado')}</span></div><div class="form-grid"><label>Data do andamento *<input id="hDate" type="date" value="${today()}"></label><label>Horário<input id="hTime" type="time"></label><label>Canal<select id="hChannel"><option>WhatsApp</option><option>Telefone</option><option>Presencial</option><option>E-mail</option><option>Outro</option></select></label><label>Situação *<select id="hStatus"><option value="aceitou">Aceitou a vaga</option><option value="rejeitou">Recusou a vaga</option><option value="sem_resposta">Não respondeu</option><option value="telefone_inativo">Telefone inativo</option><option value="contato">Enviada mensagem</option><option value="matriculou">Fez a matrícula</option><option value="retirou_encaminhamento">Retirou encaminhamento</option><option value="outro_local">Solicitou vaga em outro local</option><option value="outro">Outro</option></select></label><label class="full">Observações<textarea id="hObs" data-normalize="true" placeholder="Descreva o que ocorreu de acordo com a situação selecionada."></textarea></label></div><div class="panel"><h3>Histórico</h3>${historyTable(w)}</div>`;document.getElementById('historyModal').classList.remove('hidden');bindFieldFormatting(document.getElementById('historyForm'))}
function historyTable(w){if(!w.history?.length)return'<p class="muted">Nenhum andamento registrado.</p>';return`<div class="history-table-wrap"><table class="table"><thead><tr><th>Data</th><th>Canal</th><th>Situação</th><th>Observações</th></tr></thead><tbody>${w.history.map(h=>`<tr><td>${esc(formatDate(h.date))}<br>${esc(h.time||'')}</td><td>${esc(h.channel||'—')}</td><td><span class="badge">${esc(waitStatusLabel(h.status))}</span></td><td>${esc(h.observations||h.response||'—')}</td></tr>`).join('')}</tbody></table></div>`}
window.closeHistoryModal=()=>document.getElementById('historyModal').classList.add('hidden');
window.addWaitHistory=()=>{const id=document.getElementById('historyModal').dataset.wait,w=state.waitlist.find(x=>x.id===id);if(!w)return;const status=document.getElementById('hStatus').value;const observations=normalizeText(document.getElementById('hObs').value,'multiline');w.status=status;delete w.rejectionReason;w.history.push({id:uid(),date:document.getElementById('hDate').value||today(),time:document.getElementById('hTime').value||new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),type:'Andamento',channel:document.getElementById('hChannel').value,observations,status});save();closeHistoryModal();render();notify('Andamento salvo no histórico.')}
window.printWaitReport=id=>{const w=state.waitlist.find(x=>x.id===id);if(!w)return;const filename=`${today()}_Relatorio_Retorno_Vaga_${slug(w.crianca)}.pdf`;const hist=(w.history||[]).map(h=>`<tr><td>${esc(formatDate(h.date))}</td><td>${esc(h.channel||'')}</td><td>${esc(waitStatusLabel(h.status))}</td><td>${esc(h.observations||h.response||'')}</td></tr>`).join('');const final=`${w.status==='matriculou'?'Matrícula realizada':w.status==='rejeitou'?'Vaga recusada':w.status==='sem_resposta'?'Sem resposta':w.status==='finalizada'?'Processo finalizado':waitStatusLabel(w.status)}`;const html=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${filename}</title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;font-size:11pt;color:#111}.head{text-align:center;border-bottom:2px solid #222;padding-bottom:10px}.head h1{font-size:16pt;margin:0}.head p{margin:3px}.title{text-align:center;font-size:15pt;font-weight:bold;margin:22px 0}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #bbb}.cell{padding:7px;border-bottom:1px solid #ddd}.label{font-weight:bold;background:#f2f2f2}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #aaa;padding:6px;vertical-align:top}th{background:#eee}.signature{margin-top:60px;text-align:center}.signature span{display:inline-block;border-top:1px solid #111;width:260px;padding-top:5px}@media print{button{display:none}}</style></head><body><div class="head"><h1>CENTRO DE EDUCAÇÃO INFANTIL LINDOLPHO JOSÉ DA SILVA</h1><p>Prefeitura Municipal de Araquari — Secretaria Municipal de Educação</p><p>Rua Florentina Pereira Jasper, nº 136 — Bairro Porto Grande — Araquari/SC</p></div><div class="title">RELATÓRIO DE RETORNO DE VAGA</div><div class="grid"><div class="cell label">Criança</div><div class="cell">${esc(w.crianca)}</div><div class="cell label">Data de nascimento</div><div class="cell">${esc(formatDate(w.nascimento))}</div><div class="cell label">Destino</div><div class="cell">${esc(w.destino)}</div><div class="cell label">Turma</div><div class="cell">${esc(w.turma)}</div><div class="cell label">Responsável</div><div class="cell">${esc(w.responsavel)}</div><div class="cell label">Telefone</div><div class="cell">${esc(w.telefone||'—')}</div><div class="cell label">Recebimento da vaga</div><div class="cell">${esc(formatDate(w.recebimento))}</div><div class="cell label">Situação final</div><div class="cell">${esc(final)}</div></div><h3>Histórico do andamento</h3><table><thead><tr><th>Data</th><th>Canal</th><th>Situação</th><th>Registro</th></tr></thead><tbody>${hist}</tbody></table><p style="margin-top:22px">Relatório gerado em ${esc(formatDate(today()))}.</p><div class="signature"><span>Responsável pelo retorno</span></div><p style="font-size:9pt;margin-top:20px">Nome sugerido do arquivo: ${esc(filename)}</p><script>window.onload=()=>setTimeout(()=>window.print(),300)</script></body></html>`;const win=window.open('','_blank');win.document.write(html);win.document.close()}
function slug(s){return String(s||'documento').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_+|_+$/g,'')}

function cpfMask(v){const d=String(v||'').replace(/\D/g,'').slice(0,11);return d.replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2')}
function formatDateBr(v){if(!v)return '';const [y,m,d]=v.split('-');return `${d}/${m}/${y}`}
function renderMeimei(a){const list=(state.encaminhamentosMeimei||[]).slice().sort((x,y)=>(y.createdAt||'').localeCompare(x.createdAt||''));a.innerHTML=`<div class="oficio-actions"><button class="primary" onclick="newMeimei()">+ Novo encaminhamento</button></div><div class="panel"><h2>Encaminhamentos para a Creche Meimei</h2><p class="muted">As declarações geradas ficam arquivadas nesta base e podem ser reabertas ou impressas novamente.</p><div class="toolbar"><input id="meimeiSearch" placeholder="Pesquisar por criança, declarante, CPF ou data..." oninput="filterMeimei()"></div><div id="meimeiList"></div></div>`;filterMeimei()}
window.filterMeimei=()=>{const q=(document.getElementById('meimeiSearch')?.value||'').toLocaleLowerCase('pt-BR');const list=(state.encaminhamentosMeimei||[]).filter(x=>[x.crianca,x.declarante,x.cpf,x.data].join(' ').toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));const el=document.getElementById('meimeiList');if(!el)return;el.innerHTML=list.length?`<div class="history-table-wrap"><table class="table"><thead><tr><th>Data</th><th>Criança</th><th>Declarante</th><th>CPF</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(formatDateBr(x.data))}</td><td><b>${esc(x.crianca)}</b></td><td>${esc(x.declarante)}</td><td>${esc(x.cpf)}</td><td class="oficio-row-actions"><button onclick="editMeimei('${x.id}')">Editar</button><button onclick="printMeimei('${x.id}')">Imprimir/PDF</button><button class="danger" onclick="deleteMeimei('${x.id}')">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum encaminhamento gerado.</p>'}
window.newMeimei=()=>openMeimeiEditor();window.editMeimei=id=>openMeimeiEditor((state.encaminhamentosMeimei||[]).find(x=>x.id===id));
function openMeimeiEditor(x){const a=document.getElementById('app');document.getElementById('title').textContent=x?'Editar encaminhamento':'Novo encaminhamento';document.getElementById('subtitle').textContent='Declaração de Encaminhamento de Vaga — Creche Meimei';a.innerHTML=`<div class="panel oficio-editor"><div class="oficio-editor-head"><div><h2>Declaração de Encaminhamento de Vaga</h2><p class="muted">Preencha somente os dados variáveis. Local: Araquari/SC. A data atual já vem preenchida.</p></div><button onclick="state.view='meimei';render()">← Voltar</button></div><input type="hidden" id="mmId" value="${esc(x?.id||'')}"><div class="form-grid"><label>Nome do declarante *<input id="mmDeclarante" value="${esc(x?.declarante||'')}" data-normalize="true"></label><label>CPF do declarante *<input id="mmCpf" value="${esc(x?.cpf||'')}" inputmode="numeric" maxlength="14"></label><label class="full">Nome da criança *<input id="mmCrianca" value="${esc(x?.crianca||'')}" data-normalize="true"></label><label>Data *<input id="mmData" type="date" value="${esc(x?.data||today())}"></label><label>Local<input value="Araquari/SC" disabled></label></div><div class="actions"><button onclick="saveMeimei(false)">Salvar</button><button class="primary" onclick="saveMeimei(true)">Salvar e imprimir/PDF</button></div></div>`;const cpf=document.getElementById('mmCpf');cpf.addEventListener('input',()=>cpf.value=cpfMask(cpf.value));bindFieldFormatting(a)}
window.saveMeimei=(doPrint=false)=>{const id=document.getElementById('mmId').value||uid(),declarante=normalizeText(document.getElementById('mmDeclarante').value),cpf=cpfMask(document.getElementById('mmCpf').value),crianca=normalizeText(document.getElementById('mmCrianca').value),data=document.getElementById('mmData').value;if(!declarante||cpf.replace(/\D/g,'').length!==11||!crianca||!data)return alert('Preencha nome do declarante, CPF válido com 11 dígitos, nome da criança e data.');const i=(state.encaminhamentosMeimei||[]).findIndex(x=>x.id===id);const rec={id,declarante,cpf,crianca,data,local:'Araquari/SC',createdAt:i>=0?state.encaminhamentosMeimei[i].createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(i>=0)state.encaminhamentosMeimei[i]=rec;else state.encaminhamentosMeimei.push(rec);const generated=(state.generatedDocs||[]).find(g=>g.id===id&&g.template==='meimei');if(generated){generated.data={...generated.data,declarante,cpf,crianca,data};generated.reference=crianca;generated.updatedAt=rec.updatedAt}save();notify('Encaminhamento salvo e arquivado.');if(doPrint)openMeimeiPrint(rec);else{state.view='meimei';render()}}
window.deleteMeimei=id=>{const x=(state.encaminhamentosMeimei||[]).find(r=>r.id===id);if(!x)return;if(!confirm(`Excluir o encaminhamento de ${x.crianca}?`))return;state.encaminhamentosMeimei=state.encaminhamentosMeimei.filter(r=>r.id!==id);state.generatedDocs=(state.generatedDocs||[]).filter(g=>g.id!==id);save();render();notify('Encaminhamento excluído.')};window.printMeimei=id=>{const x=(state.encaminhamentosMeimei||[]).find(r=>r.id===id);if(x)openMeimeiPrint(x)};
function openMeimeiPrint(x){const headerUrl=new URL('timbrado-cabecalho.png',location.href).href,footerUrl=new URL('timbrado-rodape.png',location.href).href;const [y,m,d]=x.data.split('-');const meses=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];const dataExt=`${Number(d)} de ${meses[Number(m)-1]} de ${y}`;const w=window.open('','_blank');if(!w)return alert('O navegador bloqueou a janela de impressão. Permita pop-ups.');w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Encaminhamento - ${esc(x.crianca)}</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#fff;font-family:Arial,Helvetica,sans-serif;color:#111}.page{width:210mm;height:297mm;position:relative;margin:auto;overflow:hidden}.top{position:absolute;top:0;left:6mm;width:198mm;height:23.76mm}.bottom{position:absolute;bottom:0;left:6mm;width:198mm;height:66mm}.content{position:absolute;top:37mm;left:16mm;right:16mm;bottom:39mm;font-size:11.2pt;line-height:1.55}.title{text-align:center;font-weight:700;font-size:14pt;margin:0 0 14mm}.text{text-align:justify;margin:0 0 7mm}.docs{font-weight:700;margin:7mm 0 10mm;padding-left:5mm}.docs div{margin:1mm 0}.date{text-align:center;margin:10mm 0 30mm}.signatures{display:flex;justify-content:space-between;gap:18mm;text-align:center}.sig{width:72mm;border-top:1px solid #111;padding-top:2mm}.name{font-size:9.5pt;margin-top:2mm}@media print{.page{margin:0}}</style></head><body><div class="page"><img class="top" src="${headerUrl}"><img class="bottom" src="${footerUrl}"><main class="content"><div class="title">DECLARAÇÃO DE ENCAMINHAMENTO DE VAGA</div><p class="text">Eu, <b>${esc(x.declarante)}</b>, inscrito(a) no CPF sob o nº <b>${esc(x.cpf)}</b>, declaro que o responsável legal do menor <b>${esc(x.crianca)}</b> foi encaminhado por esta unidade para o CEI credenciado por não haver vaga nos CEIs da Rede Municipal próximos ao seu domicílio. O responsável deverá comparecer munido dos documentos abaixo relacionados na <b>CRECHE MEIMEI</b> para efetuar matrícula conforme orientação da Secretaria Municipal de Educação no prazo de 3 dias após a data de assinatura deste documento.</p><div class="docs"><div>• Certidão de Nascimento e/ou CPF;</div><div>• Número do cartão SUS;</div><div>• Número de identificação social (Bolsa Família) - para as famílias cadastradas no CadÚnico;</div><div>• Declaração do Posto de Saúde, atestando a regularidade das vacinas;</div><div>• Declaração de trabalho atualizada (para matrícula de crianças de 04 meses a 05 anos, 11 meses e 29 dias);</div><div>• Comprovante de residência atualizado;</div><div>• Documentos pessoais dos pais e/ou responsáveis.</div></div><div class="date">Araquari/SC, ${esc(dataExt)}.</div><div class="signatures"><div><div class="sig">Assinatura do Declarante</div><div class="name">${esc(x.declarante)}</div></div><div><div class="sig">Assinatura do Responsável</div></div></div></main></div><script>window.onload=()=>setTimeout(()=>window.print(),700)<\/script></body></html>`);w.document.close()}

function oficioNextNumber(){const y=new Date().getFullYear();let max=0;(state.oficios||[]).forEach(o=>{if(Number(o.ano||y)!==y)return;const n=parseInt(String(o.numero||'').match(/\d+/)?.[0]||0,10);if(n>max)max=n});return String(max+1).padStart(3,'0')}
function oficioStatusLabel(s){return s==='finalizado'?'Finalizado':'Rascunho'}
function renderOficios(a){a.innerHTML=`<div class="oficio-actions"><button class="primary" onclick="newOficio()">+ Novo ofício</button></div><div class="panel"><div class="toolbar"><input id="oficioSearch" placeholder="Pesquisar por número, destinatário ou assunto..." oninput="filterOficios()"><select id="oficioFilter" onchange="filterOficios()"><option value="">Todos</option><option value="rascunho">Rascunhos</option><option value="finalizado">Finalizados</option><option value="com-pdf">Com PDF assinado</option><option value="sem-pdf">Aguardando assinatura</option></select></div><div id="oficioList"></div></div><input id="signedPdfInput" type="file" accept="application/pdf,.pdf" hidden onchange="handleSignedPdf(this)">`;filterOficios()}
window.filterOficios=()=>{const q=(document.getElementById('oficioSearch')?.value||'').toLocaleLowerCase('pt-BR'),f=document.getElementById('oficioFilter')?.value||'',list=(state.oficios||[]).filter(o=>{const statusOk=!f||(f==='com-pdf'?!!o.signedPdfData:(f==='sem-pdf'?!o.signedPdfData:o.status===f));return statusOk&&[o.numero,o.destinatario,o.assunto,o.data].join(' ').toLocaleLowerCase('pt-BR').includes(q)}).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));const el=document.getElementById('oficioList');if(!el)return;el.innerHTML=list.length?`<div class="history-table-wrap"><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Destinatário</th><th>Assunto</th><th>Situação</th><th>Assinatura</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><b>${esc(o.numero)}/${esc(o.ano)}</b></td><td>${esc(formatDate(o.data))}</td><td>${esc(o.destinatario)}</td><td>${esc(o.assunto)}</td><td><span class="badge">${oficioStatusLabel(o.status)}</span></td><td>${o.signedPdfData?'<span class="badge signed-pdf-badge">✓ PDF assinado</span>':'<span class="muted">Aguardando</span>'}</td><td class="oficio-row-actions"><button onclick="editOficio('${o.id}')">Editar</button><button onclick="printOficio('${o.id}')">Imprimir/PDF</button>${o.signedPdfData?`<button onclick="viewSignedPdf('${o.id}')">Visualizar assinado</button><button onclick="downloadSignedPdf('${o.id}')">Baixar PDF</button><button onclick="attachSignedPdf('${o.id}')">Substituir PDF</button><button class="danger" onclick="removeSignedPdf('${o.id}')">Remover PDF</button>`:`<button onclick="attachSignedPdf('${o.id}')">Anexar PDF assinado</button>`}<button class="danger" onclick="deleteOficio('${o.id}')">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum ofício cadastrado.</p>'}
window.newOficio=()=>openOficioEditor(null)
window.editOficio=id=>openOficioEditor((state.oficios||[]).find(o=>o.id===id))
window.deleteOficio=id=>{const o=(state.oficios||[]).find(x=>x.id===id);if(!o)return;const numero=`${o.numero||''}/${o.ano||''}`;if(!confirm(`Excluir o Ofício nº ${numero}?\n\nEsta ação removerá o ofício da lista${o.signedPdfData?' e também o PDF assinado anexado':''}. A numeração não será reutilizada automaticamente.`))return;state.oficios=(state.oficios||[]).filter(x=>x.id!==id);state.generatedDocs=(state.generatedDocs||[]).filter(x=>x.id!==id);save();notify(`Ofício nº ${numero} excluído.`);if(state.view==='oficios')filterOficios();else if(state.view==='documentos')renderDocumentosTab();updateDataStatus()}
let pendingSignedPdfOficioId=null;
window.attachSignedPdf=id=>{const o=(state.oficios||[]).find(x=>x.id===id);if(!o)return;pendingSignedPdfOficioId=id;const input=document.getElementById('signedPdfInput');if(!input)return;input.value='';input.click()}
window.handleSignedPdf=input=>{const file=input.files?.[0],id=pendingSignedPdfOficioId;pendingSignedPdfOficioId=null;if(!file||!id)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))return alert('Selecione um arquivo PDF.');if(file.size>20*1024*1024)return alert('O PDF deve ter no máximo 20 MB.');const o=(state.oficios||[]).find(x=>x.id===id);if(!o)return;const reader=new FileReader();reader.onload=()=>{o.signedPdfData=reader.result;o.signedPdfName=file.name;o.signedPdfSize=file.size;o.signedPdfAttachedAt=new Date().toISOString();save();notify('PDF assinado anexado ao ofício.');if(state.view==='oficios')filterOficios();else if(state.view==='documentos')renderDocumentosTab();updateDataStatus()};reader.onerror=()=>alert('Não foi possível ler o PDF.');reader.readAsDataURL(file)}
function signedPdfBlob(o){if(!o?.signedPdfData)return null;const [head,b64]=o.signedPdfData.split(',');const mime=(head.match(/data:([^;]+)/)||[])[1]||'application/pdf';const bin=atob(b64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}
window.viewSignedPdf=id=>{const o=(state.oficios||[]).find(x=>x.id===id);const blob=signedPdfBlob(o);if(!blob)return alert('Este ofício não possui PDF assinado.');const url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}
window.downloadSignedPdf=id=>{const o=(state.oficios||[]).find(x=>x.id===id);const blob=signedPdfBlob(o);if(!blob)return alert('Este ofício não possui PDF assinado.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=o.signedPdfName||`Oficio_${o.numero}_${o.ano}_assinado.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.removeSignedPdf=id=>{const o=(state.oficios||[]).find(x=>x.id===id);if(!o?.signedPdfData)return;if(!confirm(`Remover o PDF assinado do Ofício nº ${o.numero}/${o.ano}?\n\nO ofício elaborado continuará arquivado.`))return;delete o.signedPdfData;delete o.signedPdfName;delete o.signedPdfSize;delete o.signedPdfAttachedAt;save();notify('PDF assinado removido.');if(state.view==='oficios')filterOficios();else if(state.view==='documentos')renderDocumentosTab();updateDataStatus()}
let oficioSelectedFigure=null;
function legacyOficioHtml(o){if(o?.corpoHtml)return o.corpoHtml;return esc(o?.corpo||'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('')}
function oficioEditorHtml(){return document.getElementById('ofCorpo')?.innerHTML||''}
function oficioEditorText(){return (document.getElementById('ofCorpo')?.innerText||'').trim()}
function oficioSignerFields(a={},i=0){return `<div class="signer-entry"><label>Nome para assinatura<input data-signer-name value="${esc(a.nome||'')}"></label><label>Função<input data-signer-role value="${esc(a.funcao||'')}"></label>${i?'<button type="button" onclick="this.closest(\'.signer-entry\').remove()">Remover</button>':''}</div>`}
window.addOficioSigner=()=>{const root=document.getElementById('ofSigners');root.insertAdjacentHTML('beforeend',oficioSignerFields({},root.children.length))};
function openOficioEditor(o){const y=new Date().getFullYear(),num=o?.numero||oficioNextNumber(),date=o?.data||today();document.getElementById('app').innerHTML=`<div class="panel oficio-editor"><div class="oficio-editor-head"><div><h2>${o?'Editar':'Novo'} ofício</h2><p class="muted">Padrão baseado no ofício institucional fornecido.</p></div><button onclick="render()">Voltar</button></div><input type="hidden" id="ofId" value="${esc(o?.id||'')}"><div class="form-grid"><label>Número *<input id="ofNumero" value="${esc(num)}"></label><label>Ano *<input id="ofAno" type="number" value="${esc(o?.ano||y)}"></label><label>Data *<input id="ofData" type="date" value="${esc(date)}"></label><label>Destinatário *<input id="ofDest" value="${esc(o?.destinatario||'')}" placeholder="Ex.: Ao Setor de Compras"></label><label class="full">Assunto *<input id="ofAssunto" value="${esc(o?.assunto||'')}" placeholder="Ex.: Solicitação de compra de torneiras de bancada"></label><div class="full"><label>Texto do ofício *</label><div class="oficio-rich-toolbar"><button type="button" onclick="document.getElementById('ofImageInput').click()">📷 Inserir imagem</button><select id="ofImageSize" onchange="resizeOficioImage(this.value)"><option value="">Tamanho da imagem</option><option value="30">Pequena</option><option value="55">Média</option><option value="85">Grande</option><option value="100">Largura total</option></select><button type="button" onclick="captionOficioImage()">Legenda</button><button type="button" class="danger" onclick="removeOficioImage()">Remover imagem</button><input id="ofImageInput" type="file" accept="image/png,image/jpeg,image/webp" hidden onchange="insertOficioImage(this)"></div><p class="oficio-rich-hint">Posicione o cursor no texto antes de inserir. Clique em uma imagem para alterar tamanho, legenda ou removê-la.</p><div id="ofCorpo" class="oficio-rich-editor" contenteditable="true">${legacyOficioHtml(o)}</div></div><label class="full">Anexos / observações internas<input id="ofAnexos" value="${esc(o?.anexos||'')}" placeholder="Opcional"></label><div class="full"><div class="signer-heading"><b>Assinaturas</b><button type="button" onclick="addOficioSigner()">+ Adicionar assinante</button></div><div id="ofSigners">${(Array.isArray(o?.assinantes)&&o.assinantes.length?o.assinantes:[{nome:o?.assinatura||'Alysson Christiano Primor',funcao:o?.funcao||'Diretor Adjunto — CEI Lindolpho José da Silva'}]).map((a,i)=>oficioSignerFields(a,i)).join('')}</div></div></div><div class="oficio-helper"><label>Texto-base (opcional)<input id="ofResumo" placeholder="Ex.: solicitar manutenção de três aparelhos de ar-condicionado"></label><button onclick="oficioTextoBase()">Montar texto-base</button></div><div class="actions"><button onclick="saveOficio('rascunho')">Salvar rascunho</button><button onclick="saveOficio('finalizado',true)">Finalizar e imprimir/PDF</button></div></div>`;oficioSelectedFigure=null;const ed=document.getElementById('ofCorpo');ed.addEventListener('click',e=>{document.querySelectorAll('#ofCorpo figure.selected').forEach(x=>x.classList.remove('selected'));const f=e.target.closest('figure');if(f){oficioSelectedFigure=f;f.classList.add('selected')}else oficioSelectedFigure=null})}
window.insertOficioImage=input=>{const file=input.files?.[0];if(!file)return;if(file.size>5*1024*1024){alert('Escolha uma imagem de até 5 MB.');input.value='';return}const reader=new FileReader();reader.onload=()=>{const ed=document.getElementById('ofCorpo');ed.focus();const fig=document.createElement('figure');fig.dataset.width='55';fig.innerHTML=`<img src="${reader.result}" alt="Imagem inserida no ofício" style="width:55%"><figcaption></figcaption>`;const sel=window.getSelection();if(sel&&sel.rangeCount&&ed.contains(sel.anchorNode)){const r=sel.getRangeAt(0);r.deleteContents();r.insertNode(fig);r.setStartAfter(fig);r.collapse(true);sel.removeAllRanges();sel.addRange(r)}else ed.appendChild(fig);oficioSelectedFigure=fig;document.querySelectorAll('#ofCorpo figure.selected').forEach(x=>x.classList.remove('selected'));fig.classList.add('selected');input.value=''};reader.readAsDataURL(file)};
window.resizeOficioImage=v=>{if(!v||!oficioSelectedFigure)return;if(!document.getElementById('ofCorpo')?.contains(oficioSelectedFigure))return;const img=oficioSelectedFigure.querySelector('img');if(img){img.style.width=v+'%';oficioSelectedFigure.dataset.width=v}document.getElementById('ofImageSize').value=''};
window.captionOficioImage=()=>{if(!oficioSelectedFigure)return alert('Clique primeiro na imagem.');let cap=oficioSelectedFigure.querySelector('figcaption');if(!cap){cap=document.createElement('figcaption');oficioSelectedFigure.appendChild(cap)}const val=prompt('Legenda da imagem:',cap.textContent||'');if(val!==null)cap.textContent=val.trim()};
window.removeOficioImage=()=>{if(!oficioSelectedFigure)return alert('Clique primeiro na imagem.');if(confirm('Remover esta imagem do ofício?')){oficioSelectedFigure.remove();oficioSelectedFigure=null}};
window.oficioTextoBase=()=>{const r=document.getElementById('ofResumo').value.trim();if(!r)return alert('Descreva brevemente o que deseja solicitar ou comunicar.');const corpo=document.getElementById('ofCorpo');if(oficioEditorText()&&!confirm('Substituir o texto atual pelo texto-base?'))return;corpo.innerHTML=`<p>Prezados(as),</p><p>Cumprimentando-o(a) cordialmente, venho por meio deste ${esc(r.replace(/[.]$/,''))}.</p><p>Agradecemos desde já a atenção e permanecemos à disposição para eventuais esclarecimentos.</p><p>Atenciosamente,</p>`}
function collectOficio(){return {id:document.getElementById('ofId').value||uid(),numero:document.getElementById('ofNumero').value.trim(),ano:document.getElementById('ofAno').value.trim(),data:document.getElementById('ofData').value,destinatario:document.getElementById('ofDest').value.trim(),assunto:document.getElementById('ofAssunto').value.trim(),corpo:oficioEditorText(),corpoHtml:oficioEditorHtml(),anexos:document.getElementById('ofAnexos').value.trim(),assinantes:[...document.querySelectorAll('#ofSigners .signer-entry')].map(row=>({nome:row.querySelector('[data-signer-name]').value.trim(),funcao:row.querySelector('[data-signer-role]').value.trim()})).filter(a=>a.nome||a.funcao)}}
window.saveOficio=(status,doPrint=false)=>{const o=collectOficio();if(!o.numero||!o.ano||!o.data||!o.destinatario||!o.assunto||!o.corpo)return alert('Preencha número, ano, data, destinatário, assunto e texto.');const duplicate=(state.oficios||[]).find(x=>x.id!==o.id&&String(x.numero)===String(o.numero)&&String(x.ano)===String(o.ano));if(duplicate)return alert(`Já existe o Ofício nº ${o.numero}/${o.ano}.`);if(o.assinantes.some(a=>!a.nome))return alert('Informe o nome de cada assinante ou remova a linha vazia.');o.assinatura=o.assinantes[0]?.nome||'';o.funcao=o.assinantes[0]?.funcao||'';const i=(state.oficios||[]).findIndex(x=>x.id===o.id);o.status=status;o.updatedAt=new Date().toISOString();o.createdAt=i>=0?state.oficios[i].createdAt:o.updatedAt;if(i>=0){const old=state.oficios[i];o.signedPdfData=old.signedPdfData;o.signedPdfName=old.signedPdfName;o.signedPdfSize=old.signedPdfSize;o.signedPdfAttachedAt=old.signedPdfAttachedAt;state.oficios[i]=o}else state.oficios.push(o);save();notify(status==='finalizado'?'Ofício finalizado e salvo.':'Rascunho salvo.');if(doPrint)printOficio(o.id);else{state.view='oficios';render()}}
function formatLongDate(iso){if(!iso)return '';const [y,m,d]=iso.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(y,m-1,d))}
function oficioPrintHtml(o){
  const rawNumero=String(o.numero||'').trim();
  const ano=String(o.ano||'').trim();
  const numeroCompleto=rawNumero.includes('/')?rawNumero:(ano?`${rawNumero}/${ano}`:rawNumero);
  const paragraphs=o.corpoHtml||esc(o.corpo||'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');
  const headerUrl=new URL('timbrado-cabecalho.png',location.href).href;
  const footerUrl=new URL('timbrado-rodape.png',location.href).href;
  const dateText=o.data?formatLongDate(o.data):formatLongDate(today());
  const destinatario=esc(o.destinatario||'');
  const cargo=esc(o.cargo||'');
  const assinantes=(Array.isArray(o.assinantes)&&o.assinantes.length?o.assinantes:[{nome:o.assinatura||'Alysson Christiano Primor',funcao:o.funcao||'Diretor Adjunto — CEI Lindolpho José da Silva'}]).filter(a=>a.nome);
  const sigHtml=a=>`<div class="signature"><div class="sig-line"></div><b>${esc(a.nome)}</b><span>${esc(a.funcao||'')}</span></div>`;
  const assinaturas=assinantes.slice(0,2).map(sigHtml).join('');
  const extraPages=[];for(let i=2;i<assinantes.length;i+=8)extraPages.push(`<div class="page continuation"><img class="letterhead-top" src="${headerUrl}"><img class="letterhead-bottom" src="${footerUrl}"><main class="content"><div class="institution">CENTRO DE EDUCAÇÃO INFANTIL LINDOLPHO JOSÉ DA SILVA</div><div class="number">Assinaturas — Ofício nº ${esc(numeroCompleto)}</div><div class="signatures">${assinantes.slice(i,i+8).map(sigHtml).join('')}</div></main></div>`);
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Ofício ${esc(numeroCompleto)}</title><style>
  @page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#111;font-family:Arial,Helvetica,sans-serif}.page{width:210mm;height:297mm;position:relative;margin:0 auto;overflow:hidden;background:#fff}.letterhead-top{position:absolute;left:6mm;top:0;width:198mm;height:23.76mm;object-fit:fill}.letterhead-bottom{position:absolute;left:6mm;bottom:0;width:198mm;height:66mm;object-fit:fill}.content{position:absolute;left:18mm;right:18mm;top:42mm;bottom:42mm;font-size:11.5pt;line-height:1.34}.institution{font-weight:700;margin:0 0 10mm}.number{font-weight:700;margin:0 0 13mm}.date{margin:0 0 7mm}.recipient{margin:0 0 6mm}.recipient div+div{margin-top:1.5mm}.subject{font-weight:700;margin:0 0 6mm}.body p{margin:0 0 5mm;text-align:justify}.body figure{margin:5mm auto;text-align:center;break-inside:avoid}.body figure img{max-width:100%;height:auto}.body figcaption{font-size:9pt;color:#555;margin-top:1.5mm}.signatures{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:12mm;row-gap:9mm;margin-top:26mm;break-inside:avoid}.signature{text-align:center;line-height:1.25;min-width:0;break-inside:avoid}.continuation{break-before:page;page-break-before:always}.continuation .signatures{margin-top:22mm;row-gap:22mm}.sig-line{border-top:1px solid #111;margin-bottom:2mm}.signature b,.signature span{display:block}.attachments{font-size:9.5pt;margin-top:7mm}@media print{html,body{width:210mm;height:297mm}.page{margin:0;print-color-adjust:exact;-webkit-print-color-adjust:exact}}
  </style></head><body><div class="page"><img class="letterhead-top" src="${headerUrl}"><img class="letterhead-bottom" src="${footerUrl}"><main class="content"><div class="institution">CENTRO DE EDUCAÇÃO INFANTIL LINDOLPHO JOSÉ DA SILVA</div><div class="number">Ofício nº ${esc(numeroCompleto)}</div><div class="date">Araquari (SC), ${esc(dateText)}.</div><div class="recipient"><div>${/^ao\b|^à\b/i.test(o.destinatario||'')?'':'Ao '}${destinatario}</div>${cargo?`<div>${cargo}</div>`:''}</div><div class="subject">Assunto: ${esc(o.assunto||'')}${/[.!?]$/.test(o.assunto||'')?'':'.'}</div><div class="body">${paragraphs}</div><div class="signatures">${assinaturas}</div>${o.anexos?`<div class="attachments"><b>Anexos:</b> ${esc(o.anexos)}</div>`:''}</main></div>${extraPages.join('')}<script>window.onload=()=>setTimeout(()=>window.print(),700)<\/script></body></html>`;
}
function openOficioPrint(o){const w=window.open('','_blank');if(!w)return alert('O navegador bloqueou a janela de impressão. Permita pop-ups para este arquivo.');w.document.open();w.document.write(oficioPrintHtml(o));w.document.close()}
window.printOficio=id=>{const o=(state.oficios||[]).find(x=>x.id===id);if(o)openOficioPrint(o)};
function today(){return new Date().toISOString().slice(0,10)}
function renderGenerator(a){
  const cards=Object.entries(documentTemplates).map(([id,t])=>`<div class="doc-template"><div class="doc-icon">${t.icon}</div><div><h3>${t.name}</h3><p>${t.description}</p></div><button class="primary" onclick="openDocGen('${id}')">Preencher</button></div>`).join('');
  return a.innerHTML=`<div class="panel intro"><h2>📝 Gerar Documentos</h2><p>Preencha os dados uma única vez e gere o documento pronto para imprimir ou salvar em PDF. Os modelos oficiais poderão ser substituídos pelos formulários originais do CEI sem mudar o restante do sistema.</p></div><div class="doc-template-grid">${cards}</div><div class="panel"><h2>Documentos gerados recentemente</h2>${state.generatedDocs?.length?`<table class="table"><thead><tr><th>Documento</th><th>Data</th><th>Referência</th><th>Ação</th></tr></thead><tbody>${state.generatedDocs.slice().reverse().slice(0,10).map(d=>`<tr><td><b>${esc(d.name)}</b></td><td>${esc(d.date)}</td><td>${esc(d.reference||'—')}</td><td><button onclick="previewGenerated('${d.id}')">Visualizar e imprimir</button><button onclick="reopenGenerated('${d.id}')">Editar e imprimir</button><button class="danger" onclick="deleteGeneratedDoc('${d.id}')">Excluir</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">Nenhum documento gerado ainda.</p>'}</div>`;
}
window.openDocGen=id=>{const t=documentTemplates[id];if(!t)return;document.getElementById('docGenModal').dataset.editId='';document.getElementById('docGenTitle').textContent=`${t.icon} ${t.name}`;document.getElementById('docGenForm').innerHTML=`<p class="hint">${t.description}</p><div class="form-grid">${t.fields.map(([key,label,type,placeholder])=>{if(type==='select'){return `<label>${label}<select data-docfield="${key}">${placeholder.split('|').map(o=>`<option>${o}</option>`).join('')}</select></label>`}const phoneAttr=key==='telefone'?'data-phone="true" inputmode="numeric" maxlength="15"':'';const normAttr=key!=='emailsGoogle'&&(type==='text'||type==='textarea')?'data-normalize="true"':'';return `<label class="${type==='textarea'?'full':''}">${label}<${type==='textarea'?'textarea':'input'} data-docfield="${key}" ${phoneAttr} ${normAttr} ${type!=='textarea'?`type="${type}"`:''} placeholder="${esc(placeholder.replaceAll('\\n','\n'))}"></${type==='textarea'?'textarea':'input'}></label>`}).join('')}</div>`;const date=document.querySelector('[data-docfield="data"]');if(date)date.value=today();if(id==='verdes'){const inst=document.querySelector('[data-docfield="instituicao"]');if(inst&&!inst.value)inst.value='CEI Lindolpho José da Silva';}['cpf','cpfResponsavel','cpfCrianca'].forEach(key=>{const cpf=document.querySelector(`[data-docfield="${key}"]`);if(cpf)cpf.addEventListener('input',()=>cpf.value=cpfMask(cpf.value))});bindFieldFormatting(document.getElementById('docGenForm'));document.getElementById('docGenModal').dataset.template=id;document.getElementById('docGenModal').classList.remove('hidden')};
window.closeDocGen=()=>{const modal=document.getElementById('docGenModal');modal.classList.add('hidden');modal.dataset.editId=''};
function getGeneratedData(){const id=document.getElementById('docGenModal').dataset.template,t=documentTemplates[id],data={};document.querySelectorAll('#docGenForm [data-docfield]').forEach(e=>data[e.dataset.docfield]=normalizeFieldValue(e.dataset.docfield,e.value));return {id,t,data}}
window.generateDocument=()=>{const {id,t,data}=getGeneratedData();const required=(id==='oficio'?['destinatario','assunto','corpo']:id==='meimei'?['declarante','cpf','crianca','data']:id==='verdes'?['crianca','telefone','nacionalidade','nascimento','sexo','responsavel','instituicao','serie','turno']:id==='materiais'||id==='limpeza'?['solicitante','itens']:id==='epi'?['solicitante','itens']:[]);const missing=required.filter(k=>!String(data[k]||'').trim());if(missing.length)return alert('Preencha os campos obrigatórios antes de gerar o documento.');if(id==='usoImagem'){const parsed=parseGoogleEmails(data.emailsGoogle);if(parsed.invalid.length)return alert('Informe apenas endereços @gmail.com válidos, separados por ponto e vírgula, vírgula ou uma linha por e-mail.');data.emailsGoogle=parsed.emails.join('; ')}const ref=data.crianca||data.destinatario||data.solicitante||'';const editId=document.getElementById('docGenModal').dataset.editId;state.generatedDocs=state.generatedDocs||[];const oldIndex=editId?state.generatedDocs.findIndex(g=>g.id===editId):-1;if(editId&&oldIndex<0)return alert('O documento original não foi encontrado. Feche o formulário e abra-o novamente pelo arquivo.');const previous=oldIndex>=0?state.generatedDocs[oldIndex]:null;const generated={id:previous?.id||uid(),template:id,name:t.name,date:previous?.date||new Date().toLocaleDateString('pt-BR'),reference:ref,data,createdAt:previous?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(oldIndex>=0)state.generatedDocs[oldIndex]=generated;else state.generatedDocs.push(generated);if(id==='oficio'){let numero=String(data.numero||'').trim(),ano=String(new Date().getFullYear());const m=numero.match(/^(.+?)\s*\/\s*(\d{4})$/);if(m){numero=m[1];ano=m[2]}state.oficios=state.oficios||[];const oficioIndex=state.oficios.findIndex(o=>o.id===generated.id);const former=state.oficios[oficioIndex];const oficio={...(former||{}),id:generated.id,numero:numero||former?.numero||oficioNextNumber(),ano,data:data.data||today(),destinatario:data.destinatario||'',assunto:data.assunto||'',corpo:data.corpo||'',corpoHtml:'',anexos:data.anexos||'',assinatura:former?.assinatura||'Alysson Christiano Primor',funcao:former?.funcao||'Diretor Adjunto — CEI Lindolpho José da Silva',status:'finalizado',createdAt:former?.createdAt||generated.createdAt,updatedAt:generated.updatedAt};if(oficioIndex>=0)state.oficios[oficioIndex]=oficio;else state.oficios.push(oficio)}if(id==='meimei'){state.encaminhamentosMeimei=state.encaminhamentosMeimei||[];const meimeiIndex=state.encaminhamentosMeimei.findIndex(m=>m.id===generated.id);const former=state.encaminhamentosMeimei[meimeiIndex];const meimei={id:generated.id,declarante:data.declarante,cpf:cpfMask(data.cpf),crianca:data.crianca,data:data.data,local:'Araquari/SC',createdAt:former?.createdAt||generated.createdAt,updatedAt:generated.updatedAt};if(meimeiIndex>=0)state.encaminhamentosMeimei[meimeiIndex]=meimei;else state.encaminhamentosMeimei.push(meimei)}save();openPrintWindow(t,data);closeDocGen();render()};
function openVerdesPrint(data){
  const headerUrl=new URL('timbrado-cabecalho.png',location.href).href,footerUrl=new URL('timbrado-rodape.png',location.href).href;
  const now=new Date();
  const brDate=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Sao_Paulo'}).format(now);
  const year=new Intl.DateTimeFormat('pt-BR',{year:'numeric',timeZone:'America/Sao_Paulo'}).format(now);
  const w=window.open('','_blank');if(!w)return alert('O navegador bloqueou a janela de impressão. Permita pop-ups.');
  w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Encaminhamento Verdes Mares - ${esc(data.crianca)}</title><style>
  @page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;background:#fff;font-family:Arial,Helvetica,sans-serif;color:#172033}.page{width:210mm;height:297mm;min-height:297mm;position:relative;margin:0 auto;overflow:hidden}.top{position:absolute;top:0;left:6mm;width:198mm;height:23.76mm}.bottom{position:absolute;bottom:0;left:6mm;width:198mm;height:66mm}.content{position:absolute;top:31mm;left:16mm;right:16mm;bottom:38mm}.title{text-align:center;font-size:15pt;font-weight:800;letter-spacing:.2px;margin:0 0 3mm}.subtitle{text-align:center;font-size:10pt;text-transform:uppercase;letter-spacing:1px;color:#4c6078;margin-bottom:7mm}.section{border:1px solid #cfd9e6;border-radius:3mm;overflow:hidden;margin-bottom:6mm}.section-title{background:#eef4fb;color:#163b69;font-size:9.5pt;font-weight:800;text-transform:uppercase;letter-spacing:.7px;padding:2.5mm 4mm}.grid{display:grid;grid-template-columns:1fr 1fr}.field{padding:3mm 4mm;border-top:1px solid #e0e6ee;min-height:14mm}.field:nth-child(odd){border-right:1px solid #e0e6ee}.field.full{grid-column:1/-1;border-right:0}.label{display:block;font-size:8pt;color:#607087;text-transform:uppercase;letter-spacing:.4px;margin-bottom:1.2mm}.value{font-size:11pt;font-weight:600}.signature{text-align:center;margin:22mm auto 6mm;width:85mm;border-top:1px solid #26384d;padding-top:2mm;font-size:9.5pt}.attach{border:1px solid #d6dee9;border-radius:3mm;padding:4mm 5mm;margin-bottom:6mm}.attach b{font-size:9.5pt}.attach ul{margin:2.5mm 0 0 5mm;padding-left:4mm;font-size:9.2pt;line-height:1.45}.auth{border:1px solid #cfd9e6;border-radius:3mm;padding:3mm 5mm 4mm;min-height:41mm;font-size:9.3pt}.auth h3{text-align:center;margin:0 0 7mm;font-size:10pt;text-transform:uppercase;color:#163b69}.auth-date{font-size:10.5pt}.signline{width:110mm;border-top:1px solid #26384d;margin:12mm auto 0}.signcaption{text-align:center;margin-top:2mm}@media screen{body{min-height:100vh}.page{box-shadow:0 0 0 1px #ddd}}@media print{html,body{width:210mm!important;height:297mm!important;margin:0!important;padding:0!important;overflow:hidden!important}.page{width:210mm!important;height:297mm!important;min-height:297mm!important;margin:0!important;box-shadow:none!important;print-color-adjust:exact;-webkit-print-color-adjust:exact}.top,.bottom{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
  </style></head><body><div class="page"><img class="top" src="${headerUrl}"><img class="bottom" src="${footerUrl}"><main class="content"><h1 class="title">CADASTRO DE ESTUDANTE PARA ${year}</h1><div class="subtitle">Identificação da criança</div><section class="section"><div class="section-title">Dados do estudante</div><div class="grid"><div class="field full"><span class="label">Nome completo</span><span class="value">${esc(data.crianca)}</span></div><div class="field"><span class="label">Telefone para contato</span><span class="value">${esc(data.telefone)}</span></div><div class="field"><span class="label">Nacionalidade</span><span class="value">${esc(data.nacionalidade)}</span></div><div class="field"><span class="label">Data de nascimento</span><span class="value">${esc(formatDate(data.nascimento))}</span></div><div class="field"><span class="label">Sexo</span><span class="value">${esc(data.sexo)}</span></div><div class="field full"><span class="label">Nome completo do responsável pela criança</span><span class="value">${esc(data.responsavel)}</span></div><div class="field"><span class="label">Instituição de ensino</span><span class="value">${esc(data.instituicao)}</span></div><div class="field"><span class="label">Série / Ano · Turno</span><span class="value">${esc(data.serie)} · ${esc(data.turno)}</span></div></div></section><div class="signature">Assinatura do responsável pela criança</div><div class="attach"><b>Obrigatório anexar:</b><ul><li>Cópia do comprovante de residência atualizado <i>(preferencialmente, fatura de água ou energia elétrica)</i>;</li><li>Cópia de documento da criança;</li><li>Declaração de matrícula ou de frequência.</li></ul></div><div class="auth"><h3>Autorização da Unidade Escolar</h3><div class="auth-date">Araquari, ${esc(brDate)}.</div><div class="signline"></div><div class="signcaption">Assinatura e carimbo do responsável pela unidade de ensino</div></div></main></div><script>window.onload=()=>setTimeout(()=>window.print(),700)<\/script></body></html>`);w.document.close();
}
function openUsoImagemPrint(data){
  const headerUrl=new URL('timbrado-cabecalho.png',location.href).href;
  const footerUrl=new URL('timbrado-rodape.png',location.href).href;
  const assinatura=data.data&&/^\d{4}-\d{2}-\d{2}$/.test(data.data)?new Date(`${data.data}T12:00:00-03:00`):new Date();
  const brDate=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Sao_Paulo'}).format(assinatura);
  const anoAssinatura=Number(new Intl.DateTimeFormat('pt-BR',{year:'numeric',timeZone:'America/Sao_Paulo'}).format(assinatura));
  const validade=`31 de dezembro de ${anoAssinatura+1}`;
  const field=(label,value)=>`<div class="field"><b>${label}:</b> <span class="fill">${value?esc(value):'&nbsp;'}</span></div>`;
  const emailList=parseGoogleEmails(data.emailsGoogle).emails;
  const w=window.open('','_blank');if(!w)return alert('O navegador bloqueou a janela de impressão. Permita pop-ups.');
  w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Termo de autorização de uso de imagem — ${esc(data.crianca||'2026')}</title><style>
  @page{size:A4;margin:0}*{box-sizing:border-box}html,body{margin:0;background:white;color:#1b2839;font-family:Arial,Helvetica,sans-serif}.page{position:relative;width:210mm;height:297mm;overflow:hidden;margin:0 auto;page-break-after:always;break-after:page}.page:last-of-type{page-break-after:auto;break-after:auto}.top{position:absolute;top:0;left:6mm;width:198mm;height:23.76mm}.bottom{position:absolute;bottom:0;left:6mm;width:198mm;height:66mm}.content{position:absolute;top:30mm;left:17mm;right:17mm;bottom:64mm;font-size:10pt;line-height:1.39}.title{text-align:center;font-size:13.4pt;line-height:1.23;margin:0 0 6mm;text-transform:uppercase;color:#163b69}.institution{margin:0 0 5mm;font-size:9.4pt}.block-title{font-size:10.2pt;color:#163b69;text-transform:uppercase;border-bottom:1px solid #cad7e8;margin:5mm 0 2.3mm;padding-bottom:1mm}.field{display:flex;gap:2mm;align-items:baseline;margin:2mm 0;min-height:5mm}.field b{white-space:nowrap}.fill{flex:1;border-bottom:1px solid #7488a6;min-height:5mm;word-break:break-word}.email-entry{margin:2mm 0 3mm}.email-entry b{display:block}.email-values{border-bottom:1px solid #7488a6;min-height:5mm;overflow-wrap:anywhere}.two{display:grid;grid-template-columns:1fr 1fr;gap:5mm}.intro,p{margin:4mm 0;text-align:justify}.section-title{font-size:10.3pt;color:#163b69;margin:5mm 0 2mm}.section-text{margin:2mm 0 3mm;text-align:justify}ul{padding-left:5mm;margin:2mm 0}li{margin:0 0 2.4mm;text-align:justify}.choices{border:1px solid #bdcde1;border-radius:2mm;padding:3mm 4mm;margin:3mm 0 4mm}.choices p{margin:1mm 0 2mm}.choice{display:block;margin:2.8mm 0;line-height:1.3}.box{display:inline-block;width:3.8mm;height:3.8mm;border:1.2px solid #182c49;vertical-align:-.5mm;margin-right:2mm}.small{font-size:9pt;color:#33445d}.sign{margin:11mm auto 0;text-align:center;width:115mm}.sign .rule{border-top:1px solid #172c45;height:2mm}.page:nth-of-type(2) .content{font-size:9.3pt;line-height:1.28}.page:nth-of-type(2) .title{font-size:12pt;margin-bottom:4mm}.page:nth-of-type(2) .section-title{margin:3mm 0 1.5mm}.page:nth-of-type(2) .section-text{margin:1.6mm 0 2mm}.page:nth-of-type(2) ul{margin:1.5mm 0}.page:nth-of-type(2) li{margin-bottom:1.4mm}.page:nth-of-type(2) .choices{padding:2mm 3mm;margin:2mm 0}.page:nth-of-type(2) .choice{margin:1.6mm 0}.page:nth-of-type(2) .small{margin:2mm 0}.page:nth-of-type(2) .sign{margin-top:13mm}.page-no{position:absolute;right:17mm;bottom:50mm;color:#526580;font-size:8pt}@media screen{body{background:#dde4ec;padding:15px}.page{background:white;box-shadow:0 2px 14px #8492a8;margin-bottom:15px}}@media print{html,body{width:210mm;margin:0;padding:0;background:#fff;print-color-adjust:exact;-webkit-print-color-adjust:exact}.page{box-shadow:none;margin:0}.top,.bottom{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
  </style></head><body>
  <div class="page"><img class="top" src="${headerUrl}"><img class="bottom" src="${footerUrl}"><main class="content"><h1 class="title">Termo complementar de uso de imagem e compartilhamento digital<br>(Ano letivo de ${anoAssinatura})</h1><div class="institution"><b>Instituição:</b> CEI Lindolpho José da Silva &nbsp; | &nbsp; <b>Município:</b> Araquari/SC</div>
  <h2 class="block-title">Dados do responsável legal</h2>${field('Nome',data.responsavel)}${field('CPF',cpfMask(data.cpfResponsavel||''))}${field('Endereço',data.endereco)}<div class="email-entry"><b>Conta(s) Gmail (@gmail.com) autorizada(s) para acessar o álbum:</b><div class="email-values">${emailList.length?emailList.map(esc).join('; '):'&nbsp;'}</div></div>
  <h2 class="block-title">Dados da criança</h2>${field('Nome',data.crianca)}<div class="two">${field('Nascimento',data.nascimento?formatDate(data.nascimento):'')}${field('CPF',cpfMask(data.cpfCrianca||''))}</div><div class="two">${field('Turma',data.turma)}${field('Período',data.periodo)}</div>
  <p class="intro">Este termo complementa a autorização de imagem fornecida pela Secretaria de Educação. Para organização interna e envio de registros pedagógicos às famílias, o CEI propõe as atividades digitais descritas abaixo, observados o melhor interesse da criança, a Lei nº 13.709/2018 (LGPD) e a Lei nº 15.211/2025 (Estatuto Digital da Criança e do Adolescente).</p>
  <h2 class="section-title">1. Armazenamento e agrupamento de imagens</h2><p class="section-text">O CEI utiliza o Google Fotos para guardar registros das atividades e, mediante autorização específica, pode ativar o agrupamento de rostos para localizar imagens da criança. Essa função analisa características faciais e pode envolver dados biométricos. Os grupos de rostos ficam na conta utilizada pela escola e <b>não são enviados automaticamente</b> às famílias. A unidade somente submeterá a essa função imagens de crianças para as quais haja autorização válida; as demais deverão permanecer fora do acervo com agrupamento facial ativo.</p>
  <p class="section-text">Quando autorizado o álbum digital, o CEI selecionará as imagens e convidará diretamente apenas as contas Gmail indicadas acima. Para acessá-lo, o responsável deverá entrar no Google Fotos com uma dessas contas. O CEI manterá desativado o compartilhamento por link e conferirá os participantes. O responsável não deverá convidar terceiros para o álbum. Sem autorização para agrupamento facial, a seleção das imagens será manual.</p>
  <p class="small"><b>Validade desta autorização:</b> até ${validade}. Após esse prazo, as imagens mantidas no servidor poderão ser excluídas, observadas eventuais obrigações legais de conservação.<br><b>Contato do CEI para informações, solicitações e revogação (telefone/WhatsApp):</b> (47) 3452-2185.</p></main><span class="page-no">1 / 2</span></div>
  <div class="page"><img class="top" src="${headerUrl}"><img class="bottom" src="${footerUrl}"><main class="content"><h2 class="title">Termo complementar — uso de imagem e compartilhamento digital</h2>
  <h2 class="section-title">2. Grupo oficial de WhatsApp e uso pelas famílias</h2><p class="section-text">O CEI poderá publicar registros de atividades no grupo oficial do CEI Lindolpho José da Silva apenas quando houver autorização específica para a divulgação da imagem de <b>cada criança identificável</b> na foto ou no vídeo. A equipe deverá conferir as autorizações e os participantes antes da postagem. Se esta opção for recusada, a imagem identificável da criança não será enviada ao grupo.</p>
  <p class="section-text">O grupo reúne integrantes da equipe e responsáveis participantes. As imagens enviadas podem ser vistas, salvas ou encaminhadas por eles, e os números de telefone dos membros do grupo são visíveis aos demais membros. Participar do grupo não exige autorizar a divulgação da imagem da criança.</p>
  <ul><li><b>Uso pelas famílias:</b> fotos e vídeos recebidos pelo grupo ou álbum podem ser guardados para arquivo pessoal. Não encaminhe imagens identificáveis de outras crianças fora do grupo nem as publique em redes sociais; para divulgar a própria criança, use apenas registros individuais ou nos quais as demais não possam ser identificadas.</li><li>O compartilhamento indevido pode ter consequências previstas na legislação. O CEI permanece responsável pelos cuidados que lhe cabem antes do envio.</li></ul>
  <h2 class="section-title">3. Consentimento específico do responsável</h2><p class="section-text">Marque <b>somente uma</b> das três respostas abaixo. A escolha é facultativa, não interfere na matrícula e pode ser revogada mediante contato com a unidade. Este termo não altera a autorização geral de uso de imagem eventualmente prestada em formulário próprio.</p>
  <div class="choices"><b>Escolha uma resposta:</b><span class="choice"><span class="box"></span> <b>SIM, AUTORIZO TODAS</b> as três finalidades descritas neste termo: agrupamento facial no Google Fotos para localizar registros da criança, envio de álbum digital à família e publicação de fotos e vídeos da criança no grupo oficial de WhatsApp do CEI.</span><span class="choice"><span class="box"></span> <b>NÃO AUTORIZO NENHUMA</b> dessas três finalidades.</span><span class="choice"><span class="box"></span> <b>AUTORIZO APENAS</b> as finalidades assinaladas a seguir:</span><div class="partial"><span class="choice"><span class="box"></span> A. Agrupamento facial no Google Fotos para localizar registros da criança.</span><span class="choice"><span class="box"></span> B. Envio de álbum digital à(s) conta(s) Gmail indicada(s) neste termo.</span><span class="choice"><span class="box"></span> C. Publicação da imagem da criança no grupo oficial de WhatsApp do CEI.</span></div></div>
  <p class="small">Nenhuma dessas opções autoriza o CEI a publicar a imagem da criança em redes sociais abertas.</p>
  <p class="small">A revogação valerá para usos futuros e o CEI atenderá as solicitações relativas aos dados conforme a legislação. Imagens já copiadas por terceiros podem não ser recuperáveis.</p>
  <p style="margin-top:6mm">Araquari, ${esc(brDate)}.</p><div class="sign"><div class="rule"></div>Assinatura do responsável legal</div></main><span class="page-no">2 / 2</span></div><script>window.onload=()=>setTimeout(()=>window.print(),700)<\/script></body></html>`);w.document.close();
}
function openPrintWindow(t,data){
  if(t&&t.name==='Termo de autorização de uso de imagem'){openUsoImagemPrint(data);return;}
  if(t&&t.name==='Encaminhamento para Meimei'){openMeimeiPrint({declarante:data.declarante,cpf:cpfMask(data.cpf),crianca:data.crianca,data:data.data||today()});return;}
  if(t&&t.name==='Encaminhamento para Verdes Mares'){openVerdesPrint(data);return;}
  if(t&&t.name==='Ofício'){
    let numero=String(data.numero||'').trim(),ano='';
    const m=numero.match(/^(.+?)\s*\/\s*(\d{4})$/);if(m){numero=m[1];ano=m[2]}
    openOficioPrint({numero,ano,data:data.data||today(),destinatario:data.destinatario||'',cargo:data.cargo||'',assunto:data.assunto||'',corpo:data.corpo||'',anexos:data.anexos||'',assinatura:'Alysson Christiano Primor',funcao:'Diretor Adjunto — CEI Lindolpho José da Silva'});return;
  }
  const labels={numero:'Número',destinatario:'Destinatário',cargo:'Cargo / setor',assunto:'Assunto',referencia:'Referência',data:'Data',corpo:'Texto',anexos:'Anexos',crianca:'Nome da criança',nascimento:'Data de nascimento',responsavel:'Responsável',cpf:'CPF do responsável',telefone:'Telefone',endereco:'Endereço',turma:'Turma / faixa etária',turno:'Turno solicitado',motivo:'Motivo do encaminhamento',observacoes:'Observações',solicitante:'Solicitante',periodo:'Período de uso',itens:'Materiais / itens solicitados',justificativa:'Justificativa / finalidade',quantidades:'Quantidades / tamanhos',finalidade:'Finalidade / atividade'};const rows=Object.entries(data).filter(([k,v])=>String(v||'').trim()).map(([k,v])=>`<div class="row"><div class="label">${esc(labels[k]||k)}</div><div class="value">${esc(v).replace(/\n/g,'<br>')}</div></div>`).join('');const w=window.open('','_blank');w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(t.name)}</title><style>@page{size:A4;margin:20mm 18mm}body{font-family:Arial,sans-serif;color:#111;font-size:12pt;line-height:1.45}.head{text-align:center;border-bottom:2px solid #222;padding-bottom:12px;margin-bottom:20px}.head h1{font-size:17pt;margin:0}.head p{margin:3px 0;font-size:10pt}.title{text-align:center;font-weight:bold;font-size:15pt;margin:22px 0}.row{display:grid;grid-template-columns:180px 1fr;border-bottom:1px solid #ccc;min-height:34px}.label{font-weight:bold;padding:8px;background:#f3f3f3}.value{padding:8px;white-space:normal}.signature{margin-top:65px;text-align:center}.signature span{display:inline-block;border-top:1px solid #111;padding-top:5px;width:260px}</style></head><body><div class="head"><h1>CENTRO DE EDUCAÇÃO INFANTIL LINDOLPHO JOSÉ DA SILVA</h1><p>Prefeitura Municipal de Araquari — Secretaria Municipal de Educação</p><p>Rua Florentina Pereira Jasper, nº 136 — Bairro Porto Grande — Araquari/SC</p></div><div class="title">${esc(t.name)}</div>${rows}<div class="signature"><span>Responsável pelo encaminhamento</span></div><p style="margin-top:35px">Araquari/SC, ${new Date().toLocaleDateString('pt-BR')}.</p><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}

window.previewGenerated=id=>{const g=(state.generatedDocs||[]).find(x=>x.id===id);if(g&&documentTemplates[g.template])openPrintWindow(documentTemplates[g.template],g.data||{})};
window.reopenGenerated=id=>{const g=(state.generatedDocs||[]).find(x=>x.id===id);if(!g||!documentTemplates[g.template])return;openDocGen(g.template);const modal=document.getElementById('docGenModal');modal.dataset.editId=g.id;document.getElementById('docGenTitle').textContent=`Editar ${g.name||documentTemplates[g.template].name}`;Object.entries(g.data||{}).forEach(([k,v])=>{const e=[...document.querySelectorAll('#docGenForm [data-docfield]')].find(el=>el.dataset.docfield===k);if(e)e.value=v??''})};
window.libraryTab=tab=>{if(tab==='docs'){document.getElementById('libraryContent').innerHTML=`<div class="panel"><h2>Documentos Institucionais</h2>${docTable(state.docs.filter(d=>['PPP','Regimento','BNCC','Matriz Curricular','Instrução Normativa'].includes(d.cat)))}</div>`}else if(tab==='materials'){document.getElementById('libraryContent').innerHTML=`<div class="panel"><h2>Materiais Pedagógicos</h2><p class="muted">Área preparada para planos, materiais de apoio e outros recursos pedagógicos.</p></div>`}else render()};
window.openBookModal=(b=null)=>{document.getElementById('bookModal').classList.remove('hidden');document.getElementById('bookModal').dataset.editId=b?.id||'';document.getElementById('bookModalTitle').textContent=b?'Editar livro':'Cadastrar livro';const map={bookTitle:'title',bookCutter:'cutter',bookCdd:'cdd',bookAuthor:'author',bookPublisher:'publisher',bookYear:'year',bookIsbn:'isbn',bookAge:'age',bookLocation:'location',bookQuantity:'quantity',bookNotes:'notes'};Object.entries(map).forEach(([id,k])=>{const e=document.getElementById(id);if(e)e.value=b?.[k]??(id==='bookQuantity'?1:'')});if(b&&document.getElementById('bookCategory'))document.getElementById('bookCategory').value=b.category||'Literatura Infantil'};window.closeBookModal=()=>document.getElementById('bookModal').classList.add('hidden');
window.openLoanModal=(id='')=>{
  if(id){const selected=state.books.find(b=>b.id===id);if(!selected||!bookAvailable(selected))return alert('Não há exemplares disponíveis deste livro.')}
  if(!state.books.length)return alert('Cadastre um livro no acervo antes de registrar empréstimos.');
  const selected=state.books.find(b=>b.id===id);
  document.getElementById('loanBookSearch').value=selected?`${selected.title} · ${selected.cutter||'sem Cutter'}`:'';
  document.getElementById('loanBookId').value=id||'';document.getElementById('loanBookName').textContent=selected?`${bookAvailable(selected)} de ${bookCopies(selected)} exemplar(es) disponível(is)`:'Digite o nome ou código e escolha um resultado.';
  document.getElementById('loanBookResults').classList.add('hidden');document.getElementById('loanBookSearch').setAttribute('aria-expanded','false');document.getElementById('loanReaderSearch').value='';document.getElementById('loanReaderId').value='';document.getElementById('loanReaderResults').classList.add('hidden');document.getElementById('loanReaderSearch').setAttribute('aria-expanded','false');document.getElementById('loanClass').value='';
  const due=new Date(`${libraryToday()}T12:00:00-03:00`);due.setUTCDate(due.getUTCDate()+14);document.getElementById('loanDue').value=due.toISOString().slice(0,10);
  document.getElementById('loanModal').classList.remove('hidden');if(!id)document.getElementById('loanBookSearch').focus();
};
function matchingLoanBooks(){const q=searchFold(document.getElementById('loanBookSearch').value);return q?state.books.filter(b=>searchFold(`${b.title} ${b.cutter||''}`).includes(q)).sort((a,b)=>String(a.title).localeCompare(String(b.title),'pt-BR')).slice(0,10):[]}
window.searchLoanBooks=()=>{document.getElementById('loanBookId').value='';document.getElementById('loanBookName').textContent='Selecione um dos resultados para confirmar o livro.';renderLoanBookResults()};
function renderLoanBookResults(){const results=document.getElementById('loanBookResults'),q=document.getElementById('loanBookSearch').value.trim(),books=matchingLoanBooks();results.innerHTML=q?(books.length?books.map(b=>`<button type="button" role="option" aria-selected="false" class="${bookAvailable(b)?'':'unavailable'}" ${bookAvailable(b)?`onclick="selectLoanBook('${b.id}')"`:'disabled aria-disabled="true"'} onkeydown="loanResultKey(event)"><b>${esc(b.title)}</b><small>${esc(b.cutter||'Sem Cutter')} · ${bookAvailable(b)?`${bookAvailable(b)} exemplar(es) disponível(is)`:'Indisponível — todos os exemplares emprestados'}</small></button>`).join(''):'<p>Nenhum livro corresponde à busca.</p>'):'';results.classList.toggle('hidden',!q);document.getElementById('loanBookSearch').setAttribute('aria-expanded',q?'true':'false')}
window.selectLoanBook=id=>{const b=state.books.find(x=>x.id===id);if(!b||!bookAvailable(b))return alert('Não há exemplares disponíveis deste livro.');document.getElementById('loanBookId').value=id;document.getElementById('loanBookSearch').value=`${b.title} · ${b.cutter||'sem Cutter'}`;document.getElementById('loanBookName').textContent=`${bookAvailable(b)} de ${bookCopies(b)} exemplar(es) disponível(is)`;document.getElementById('loanBookResults').classList.add('hidden');document.getElementById('loanBookSearch').setAttribute('aria-expanded','false');document.getElementById('loanPerson').focus()};
window.loanSearchKey=event=>{if(event.key==='Escape'){document.getElementById('loanBookResults').classList.add('hidden');document.getElementById('loanBookSearch').setAttribute('aria-expanded','false');return}if(!['Enter','ArrowDown'].includes(event.key))return;const options=document.querySelectorAll('#loanBookResults button:not(:disabled)');if(!options.length)return;event.preventDefault();if(event.key==='Enter'&&options.length===1){options[0].click();return}options[0].focus()};
window.loanResultKey=event=>{const options=[...document.querySelectorAll('#loanBookResults button:not(:disabled)')],index=options.indexOf(event.currentTarget);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();options[(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(event.key==='Escape'){document.getElementById('loanBookResults').classList.add('hidden');document.getElementById('loanBookSearch').setAttribute('aria-expanded','false');document.getElementById('loanBookSearch').focus()}};
window.closeLoanModal=()=>document.getElementById('loanModal').classList.add('hidden');
function matchingLoanReaders(){const q=searchFold(document.getElementById('loanReaderSearch').value);return q?state.readers.filter(r=>searchFold(`${r.name} ${r.identifier||''} ${r.turma||''}`).includes(q)).sort((a,b)=>String(a.name).localeCompare(String(b.name),'pt-BR')).slice(0,10):[]}
window.searchLoanReaders=()=>{document.getElementById('loanReaderId').value='';renderLoanReaderResults()};
function renderLoanReaderResults(){const results=document.getElementById('loanReaderResults'),q=document.getElementById('loanReaderSearch').value.trim(),readers=matchingLoanReaders();results.innerHTML=q?(readers.length?readers.map(r=>`<button type="button" role="option" aria-selected="false" class="${r.active===false?'unavailable':''}" ${r.active===false?'disabled aria-disabled="true"':`onclick="selectLoanReader('${r.id}')"`} onkeydown="loanReaderResultKey(event)"><b>${esc(r.name)}</b><small>${esc(r.identifier||r.category||'Usuário')}${r.active===false?' · Cadastro inativo':''}</small></button>`).join(''):'<p>Nenhum usuário encontrado. Cadastre a pessoa antes do empréstimo.</p>'):'';results.classList.toggle('hidden',!q);document.getElementById('loanReaderSearch').setAttribute('aria-expanded',q?'true':'false')}
window.selectLoanReader=id=>{const r=state.readers.find(x=>x.id===id);if(!r||r.active===false)return alert('Selecione um usuário ativo.');document.getElementById('loanReaderId').value=id;document.getElementById('loanReaderSearch').value=`${r.name}${r.identifier?` · ${r.identifier}`:''}`;document.getElementById('loanReaderResults').classList.add('hidden');document.getElementById('loanReaderSearch').setAttribute('aria-expanded','false');if(r.turma&&!document.getElementById('loanClass').value)document.getElementById('loanClass').value=r.turma;document.getElementById('loanDue').focus()};
window.loanReaderKey=event=>{if(event.key==='Escape'){document.getElementById('loanReaderResults').classList.add('hidden');document.getElementById('loanReaderSearch').setAttribute('aria-expanded','false');return}if(!['Enter','ArrowDown'].includes(event.key))return;const options=document.querySelectorAll('#loanReaderResults button:not(:disabled)');if(!options.length)return;event.preventDefault();if(event.key==='Enter'&&options.length===1){options[0].click();return}options[0].focus()};
window.loanReaderResultKey=event=>{const options=[...document.querySelectorAll('#loanReaderResults button:not(:disabled)')],index=options.indexOf(event.currentTarget);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();options[(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(event.key==='Escape'){document.getElementById('loanReaderResults').classList.add('hidden');document.getElementById('loanReaderSearch').setAttribute('aria-expanded','false');document.getElementById('loanReaderSearch').focus()}};
window.openReaderModal=(id='',fromLoan=false)=>{const r=state.readers.find(x=>x.id===id);const modal=document.getElementById('readerModal');modal.dataset.editId=id||'';modal.dataset.fromLoan=fromLoan?'1':'0';document.getElementById('readerModalTitle').textContent=r?'Editar usuário da biblioteca':'Cadastrar usuário da biblioteca';document.getElementById('readerName').value=r?.name||'';document.getElementById('readerCategory').value=r?.category||'Professor(a)';document.getElementById('readerIdentifier').value=r?.identifier||'';document.getElementById('readerClass').value=r?.turma||'';modal.classList.remove('hidden');document.getElementById('readerName').focus()};
window.closeReaderModal=()=>document.getElementById('readerModal').classList.add('hidden');
window.saveReader=()=>{const modal=document.getElementById('readerModal'),editId=modal.dataset.editId,name=normalizeText(document.getElementById('readerName').value),identifier=document.getElementById('readerIdentifier').value.trim(),category=document.getElementById('readerCategory').value,turma=normalizeText(document.getElementById('readerClass').value);if(!name)return alert('Informe o nome do usuário.');if(identifier&&state.readers.some(r=>r.id!==editId&&legacyReaderKey(r.identifier)===legacyReaderKey(identifier)))return alert('Esse código já pertence a outro usuário.');if(state.readers.some(r=>r.id!==editId&&legacyReaderKey(r.name)===legacyReaderKey(name)&&(!identifier||!r.identifier)))return alert('Já existe um usuário com esse nome. Edite o cadastro existente ou diferencie os usuários por código.');let reader=state.readers.find(r=>r.id===editId);if(reader){Object.assign(reader,{name,identifier,category,turma,updatedAt:new Date().toISOString()})}else{reader={id:uid(),name,identifier,category,turma,active:true,createdAt:new Date().toISOString()};state.readers.push(reader)}save();const fromLoan=modal.dataset.fromLoan==='1';closeReaderModal();if(fromLoan)selectLoanReader(reader.id);else{window.__libraryView='readers';window.__libraryReaderId=reader.id;renderLibrary(document.getElementById('app'))}notify(editId?'Usuário atualizado.':'Usuário cadastrado.')};
window.toggleReaderActive=id=>{const r=state.readers.find(x=>x.id===id);if(!r)return;if(r.active!==false&&readerLoans(id).some(l=>!l.returned))return alert('Devolva os livros em aberto antes de desativar este usuário.');r.active=r.active===false;save();renderLibrary(document.getElementById('app'));notify(r.active?'Usuário reativado.':'Usuário desativado.')};
window.openReturnModal=id=>{const l=state.loans.find(x=>x.id===id&&!x.returned);if(!l)return;document.getElementById('returnLoanId').value=id;document.getElementById('returnBookName').textContent=`${loanTitle(l)} · ${state.readers.find(r=>r.id===l.readerId)?.name||l.person||'Responsável não informado'}`;document.getElementById('returnDate').value=libraryToday();document.getElementById('returnCondition').value='Bom estado';document.getElementById('returnNotes').value='';document.getElementById('returnModal').classList.remove('hidden')};
window.closeReturnModal=()=>document.getElementById('returnModal').classList.add('hidden');
window.confirmReturnBook=()=>{const l=state.loans.find(x=>x.id===document.getElementById('returnLoanId').value&&!x.returned);if(!l)return;const date=document.getElementById('returnDate').value;if(!date||date>libraryToday()||(loanDateIso(l.date)&&date<loanDateIso(l.date)))return alert('Informe uma data de devolução entre a retirada e hoje.');l.returned=true;l.returnDate=date;l.returnCondition=document.getElementById('returnCondition').value;l.returnNotes=document.getElementById('returnNotes').value.trim();l.updatedAt=new Date().toISOString();const b=state.books.find(x=>x.id===l.bookId);if(b)b.status='Disponível';save();closeReturnModal();renderLibrary(document.getElementById('app'));notify('Devolução registrada.')};
window.returnBook=id=>openReturnModal(id);
window.openRenewModal=id=>{const l=state.loans.find(x=>x.id===id&&!x.returned);if(!l)return;document.getElementById('renewLoanId').value=id;document.getElementById('renewBookName').textContent=`${loanTitle(l)} · Devolução atual: ${loanDateLabel(l.due)}`;const base=new Date(`${[loanDateIso(l.due),libraryToday()].sort().pop()}T12:00:00-03:00`);base.setUTCDate(base.getUTCDate()+14);document.getElementById('renewDue').value=base.toISOString().slice(0,10);document.getElementById('renewModal').classList.remove('hidden')};
window.closeRenewModal=()=>document.getElementById('renewModal').classList.add('hidden');
window.confirmRenewLoan=()=>{const l=state.loans.find(x=>x.id===document.getElementById('renewLoanId').value&&!x.returned);if(!l)return;const due=document.getElementById('renewDue').value,previous=loanDateIso(l.due);if(!due||due<=libraryToday()||(previous&&due<=previous))return alert('A nova data deve ser posterior à data prevista atual e a hoje.');l.renewals=Array.isArray(l.renewals)?l.renewals:[];l.renewals.push({previousDue:l.due,newDue:due,at:new Date().toISOString()});l.due=due;l.updatedAt=new Date().toISOString();save();closeRenewModal();renderLibrary(document.getElementById('app'));notify('Empréstimo renovado.')};
window.archiveDoc=id=>{const d=state.docs.find(x=>x.id===id);if(!d)return;d.status=d.status==='Ativo'?'Arquivado':'Ativo';d.audit=(d.audit||[]).concat({action:d.status==='Arquivado'?'Arquivou':'Restaurou',at:new Date().toISOString()});save();render()};
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});document.getElementById('uploadBtn')?.addEventListener('click',()=>document.getElementById('modal').classList.remove('hidden'));document.getElementById('cancel').onclick=()=>document.getElementById('modal').classList.add('hidden');document.getElementById('save').onclick=()=>{const name=normalizeText(document.getElementById('docName').value);if(!name)return alert('Informe o nome do documento.');const cat=document.getElementById('docCat').value;state.docs.push({id:uid(),name,cat,status:'Ativo',protected:['PPP','Regimento','BNCC','Matriz Curricular','APP','Conselho Escolar','Ata'].includes(cat),date:new Date().toLocaleDateString('pt-BR'),audit:[{action:'Criou',at:new Date().toISOString()}]});save();document.getElementById('docName').value='';document.getElementById('fileInput').value='';document.getElementById('modal').classList.add('hidden');render()};
document.getElementById('bookSave').onclick=()=>{const title=normalizeText(document.getElementById('bookTitle').value);if(!title)return alert('Informe o título do livro.');const authors=getAuthors(),cutter=document.getElementById('bookCutter').value.trim();if(!cutter)return alert('Informe ou gere um código Cutter.');const editId=document.getElementById('bookModal').dataset.editId,hit=cutterConflict(cutter,editId);if(hit)return alert(`O código Cutter ${cutter} já está em uso por: ${hit.title}. Use “Sugerir livre” para obter outro código.`);const quantity=Number(document.getElementById('bookQuantity').value);if(!Number.isInteger(quantity)||quantity<1)return alert('Informe uma quantidade válida de exemplares.');if(editId&&quantity<Math.max(activeBookLoans(editId).length,...activeBookLoans(editId).map(l=>Number(l.copyNumber)||0)))return alert('A quantidade não pode ser inferior ao número de um exemplar emprestado.');const data={title,cutter,quantity,authors,author:authors.join('; '),publisher:normalizeText(document.getElementById('bookPublisher').value),year:document.getElementById('bookYear').value.trim(),notes:normalizeText(document.getElementById('bookNotes').value,'multiline')};if(editId){const b=state.books.find(x=>x.id===editId);if(b)Object.assign(b,data)}else state.books.push({id:uid(),status:'Disponível',quantity:1,...data});save();closeBookModal();render();notify(editId?'Livro atualizado.':'Livro cadastrado.')};document.getElementById('bookCutter').addEventListener('input',checkCutter);
function titleCasePtLive(value){const particles=new Set(['a','as','o','os','e','de','da','das','do','dos','em','na','nas','no','nos','para','por']);return String(value??'').split(/(\s+)/).map((part,i,arr)=>{if(/^\s+$/.test(part)||!part)return part;const lower=part.toLocaleLowerCase('pt-BR');const hasPreviousWord=arr.slice(0,i).some(x=>x&&!/^\s+$/.test(x));if(hasPreviousWord&&particles.has(lower))return lower;return lower.charAt(0).toLocaleUpperCase('pt-BR')+lower.slice(1)}).join('')}
document.addEventListener('input',e=>{const el=e.target;if(!el)return;if(el.matches('input[data-phone]')){el.value=formatPhone(el.value);return;}if(el.matches('input[data-normalize=\"true\"]')){const start=el.selectionStart,end=el.selectionEnd;el.value=titleCasePtLive(el.value);try{el.setSelectionRange(start,end)}catch(_){ }return;}if(el.matches('textarea[data-normalize=\"true\"]')){const start=el.selectionStart,end=el.selectionEnd;const v=el.value;if(v){el.value=v.charAt(0).toLocaleUpperCase('pt-BR')+v.slice(1)}try{el.setSelectionRange(start,end)}catch(_){ }}});
document.addEventListener('blur',e=>{const el=e.target;if(!(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement))return;if(el.dataset.phone==='true'){el.value=formatPhone(el.value);return;}if(el.dataset.normalize==='true'){el.value=normalizeText(el.value,el.tagName==='TEXTAREA'?'multiline':'field');}},true);
document.getElementById('loanSave').onclick=()=>{const bookId=document.getElementById('loanBookId').value,readerId=document.getElementById('loanReaderId').value,reader=state.readers.find(r=>r.id===readerId),person=reader?.name||'',turma=normalizeText(document.getElementById('loanClass').value)||reader?.turma||'',due=document.getElementById('loanDue').value,b=state.books.find(x=>x.id===bookId);if(!b)return alert('Selecione um livro.');if(!bookAvailable(b))return alert('Todos os exemplares deste livro estão emprestados.');if(!reader||reader.active===false)return alert('Selecione um usuário ativo ou cadastre uma pessoa responsável.');if(!due||due<libraryToday())return alert('A devolução prevista deve ser hoje ou uma data futura.');const active=activeBookLoans(bookId),used=new Set(active.map(l=>Number(l.copyNumber)).filter(Boolean));let copyNumber=1;while(copyNumber<=bookCopies(b)&&(used.has(copyNumber)||copyNumber<=active.filter(l=>!l.copyNumber).length))copyNumber++;state.loans.push({id:uid(),bookId,bookTitle:b.title,bookCutter:b.cutter,copyNumber,readerId,person,turma,date:libraryToday(),due,returned:false,createdAt:new Date().toISOString(),renewals:[]});b.status=bookAvailable(b)?'Disponível':'Emprestado';save();closeLoanModal();window.__libraryView='active';renderLibrary(document.getElementById('app'));notify('Empréstimo registrado.')};render();updateDataStatus();loadLocalData();

// Expose the existing navigation and registration flow to supporting browsers.
if (document.modelContext?.registerTool) {
  const register = tool => {
    try { Promise.resolve(document.modelContext.registerTool(tool)).catch(() => {}); }
    catch (_) { /* The app remains usable in browsers without WebMCP. */ }
  };
  register({
    name: 'open_admin_section', title: 'Abrir seção administrativa',
    description: 'Abre uma seção existente do CEI Admin.',
    inputSchema: { type: 'object', properties: { section: { type: 'string', enum: ['dashboard','documentos','biblioteca','atas','app','conselho','espera','agenda','pendencias','relatorios','seguranca'] } }, required: ['section'], additionalProperties: false },
    annotations: { readOnlyHint: false },
    execute({section}) {
      const button = [...document.querySelectorAll('#nav button')].find(b => b.dataset.view === section);
      if (!button) throw new Error('Seção inválida.');
      button.click();
      return { section: state.view };
    }
  });
  register({
    name: 'start_waitlist_registration', title: 'Iniciar inscrição na lista de espera',
    description: 'Abre o formulário de inscrição na lista de espera, sem salvar um registro.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    annotations: { readOnlyHint: false },
    execute(input) {
      if (input && Object.keys(input).length) throw new Error('Este comando não aceita parâmetros.');
      document.querySelector('#nav button[data-view="espera"]').click();
      openWaitModal();
      return { section: 'espera', formOpen: !document.getElementById('waitModal').classList.contains('hidden') };
    }
  });
}

let checkingShared=false;
setInterval(async()=>{
  if(checkingShared||storageBusy||document.hidden||localStorage.getItem('cei-shared-dirty')==='1'||document.querySelector('.modal:not(.hidden)')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable)return;
  checkingShared=true;
  try{const remote=await sharedRequest('GET');if(remote.data&&remote.revision!==sharedRevision){await adoptShared(remote);render();updateDataStatus();notify('Registros atualizados com as alterações feitas em outro computador.')}if(state.view==='app')await loadAppArchive();}catch(error){sharedNotice('Não foi possível atualizar a base do servidor. Verifique a conexão.');if(document.getElementById('sharedNotice'))document.getElementById('sharedNotice').hidden=false}finally{checkingShared=false}
},7000);
